@Test
public void commandlineOverridesConfiguration() throws Exception {
    Configuration config = new Configuration();
    // we use GenericCli because it allows specifying arbitrary options via "-Dfoo=bar" syntax
    CustomCommandLine commandLine = new GenericCLI(config, "/dev/null");
    config.set(PipelineOptions.AUTO_WATERMARK_INTERVAL, Duration.ofMillis(42L));
    CliFrontend cliFrontend = new CliFrontend(config, Collections.singletonList(commandLine));
    cliFrontend.parseAndRun(new String[] { "run", "-t", LocalExecutor.NAME, "-c", TestingJob.class.getName(), "-D" + PipelineOptions.AUTO_WATERMARK_INTERVAL.key() + "=142", CliFrontendTestUtils.getTestJarPath() });
    assertThat(getStdoutString(), containsString("Watermark interval is 142"));
}

@Test
public void testListOptions() throws Exception {
    // test configure all job
    {
        String[] parameters = { "-a" };
        ListOptions options = new ListOptions(CliFrontendParser.parse(CliFrontendParser.getListCommandOptions(), parameters, true));
        assertTrue(options.showAll());
        assertFalse(options.showRunning());
        assertFalse(options.showScheduled());
    }
    // test configure running job
    {
        String[] parameters = { "-r" };
        ListOptions options = new ListOptions(CliFrontendParser.parse(CliFrontendParser.getListCommandOptions(), parameters, true));
        assertFalse(options.showAll());
        assertTrue(options.showRunning());
        assertFalse(options.showScheduled());
    }
    // test configure scheduled job
    {
        String[] parameters = { "-s" };
        ListOptions options = new ListOptions(CliFrontendParser.parse(CliFrontendParser.getListCommandOptions(), parameters, true));
        assertFalse(options.showAll());
        assertFalse(options.showRunning());
        assertTrue(options.showScheduled());
    }
}

