    ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
    DataSet<Integer> baseSet = env.fromElements(1, 2);
    DataSet<Integer> result = baseSet.map((MapFunction<Integer, Integer>) value -> value * 2);
