@Test
public void getNumRecordsOutErrorsCounterRecordsCorrectNumberOfFailures() throws IOException, InterruptedException {
    TestSinkInitContext ctx = new TestSinkInitContext();
    KinesisFirehoseSink<String> kinesisFirehoseSink = new KinesisFirehoseSink<>(ELEMENT_CONVERTER_PLACEHOLDER, 12, 16, 10000, 4 * 1024 * 1024L, 5000L, 1000 * 1024L, true, "test-stream", AWSServicesTestUtils.createConfig("https://localhost"));
    SinkWriter<String> writer = kinesisFirehoseSink.createWriter(ctx);
    for (int i = 0; i < 12; i++) {
        writer.write("data_bytes", null);
    }
    assertThatExceptionOfType(CompletionException.class).isThrownBy(() -> writer.flush(true)).withCauseInstanceOf(SdkClientException.class).withMessageContaining("Unable to execute HTTP request: Connection refused: localhost/127.0.0.1:443");
    assertThat(ctx.metricGroup().getNumRecordsOutErrorsCounter().getCount()).isEqualTo(12);
    assertThat(ctx.metricGroup().getNumRecordsSendErrorsCounter().getCount()).isEqualTo(12);
}

