@Test
void testPollNextReturnMoreAvailableWhenAllSplitFetcherCloseWithLeftoverElementInQueue() throws Exception {
    FutureCompletingBlockingQueue<RecordsWithSplitIds<int[]>> elementsQueue = new FutureCompletingBlockingQueue<>();
    MockSplitReader mockSplitReader = MockSplitReader.newBuilder().setNumRecordsPerSplitPerFetch(1).setBlockingFetch(true).build();
    BlockingShutdownSplitFetcherManager<int[], MockSourceSplit> splitFetcherManager = new BlockingShutdownSplitFetcherManager<>(elementsQueue, () -> mockSplitReader);
    final MockSourceReader sourceReader = new MockSourceReader(elementsQueue, splitFetcherManager, getConfig(), new TestingReaderContext());
    // Create and add a split that only contains one record
    final MockSourceSplit split = new MockSourceSplit(0, 0, 1);
    sourceReader.addSplits(Collections.singletonList(split));
    sourceReader.notifyNoMoreSplits();
    // Add the last record to the split when the splitFetcherManager shutting down SplitFetchers
    splitFetcherManager.getInShutdownSplitFetcherFuture().thenRun(() -> split.addRecord(1));
    assertThat(sourceReader.pollNext(new TestingReaderOutput<>())).isEqualTo(InputStatus.MORE_AVAILABLE);
}

@ParameterizedTest(name = "Emit record before split addition: {0}")
@ValueSource(booleans = { true, false })
void testPerSplitWatermark(boolean emitRecordBeforeSplitAddition) throws Exception {
    MockSplitReader mockSplitReader = MockSplitReader.newBuilder().setNumRecordsPerSplitPerFetch(3).setBlockingFetch(true).build();
    MockSourceReader reader = new MockSourceReader(new FutureCompletingBlockingQueue<>(), () -> mockSplitReader, new Configuration(), new TestingReaderContext());
    SourceOperator<Integer, MockSourceSplit> sourceOperator = createTestOperator(reader, WatermarkStrategy.forGenerator((context) -> new OnEventWatermarkGenerator()), true);
    MockSourceSplit splitA = new MockSourceSplit(0, 0, 3);
    splitA.addRecord(100);
    splitA.addRecord(200);
    splitA.addRecord(300);
    MockSourceSplit splitB = new MockSourceSplit(1, 0, 3);
    splitB.addRecord(150);
    splitB.addRecord(250);
    splitB.addRecord(350);
    WatermarkCollectingDataOutput output = new WatermarkCollectingDataOutput();
    if (emitRecordBeforeSplitAddition) {
        sourceOperator.emitNext(output);
    }
    AddSplitEvent<MockSourceSplit> addSplitsEvent = new AddSplitEvent<>(Arrays.asList(splitA, splitB), new MockSourceSplitSerializer());
    sourceOperator.handleOperatorEvent(addSplitsEvent);
    // First 3 records from split A should not generate any watermarks
    CommonTestUtils.waitUtil(() -> {
        try {
            sourceOperator.emitNext(output);
        } catch (Exception e) {
            LOG.warn("Exception caught at emitting records", e);
            return false;
        }
        return output.numRecords == 3;
    }, Duration.ofSeconds(10), String.format("%d out of 3 records are received within timeout", output.numRecords));
    assertThat(output.watermarks).isEmpty();
    CommonTestUtils.waitUtil(() -> {
        try {
            sourceOperator.emitNext(output);
        } catch (Exception e) {
            LOG.warn("Exception caught at emitting records", e);
            return false;
        }
        return output.numRecords == 6;
    }, Duration.ofSeconds(10), String.format("%d out of 6 records are received within timeout", output.numRecords));
    assertThat(output.watermarks).hasSize(3);
    assertThat(output.watermarks).containsExactly(150L, 250L, 300L);
}

@Test
public void testBasics() throws InterruptedException {
    FutureCompletingBlockingQueue<Integer> queue = new FutureCompletingBlockingQueue<>(5);
    CompletableFuture<Void> future = queue.getAvailabilityFuture();
    assertTrue(queue.isEmpty());
    assertEquals(0, queue.size());
    queue.put(0, 1234);
    assertTrue(future.isDone());
    assertEquals(1, queue.size());
    assertFalse(queue.isEmpty());
    assertEquals(4, queue.remainingCapacity());
    assertNotNull(queue.peek());
    assertEquals(1234, (int) queue.peek());
    assertEquals(1234, (int) queue.poll());
    assertEquals(0, queue.size());
    assertTrue(queue.isEmpty());
    assertEquals(5, queue.remainingCapacity());
}

