@Test
public void testWritingDocuments() throws Exception {
    ResolvedSchema schema = new ResolvedSchema(Arrays.asList(Column.physical("a", DataTypes.BIGINT().notNull()), Column.physical("b", DataTypes.TIME()), Column.physical("c", DataTypes.STRING().notNull()), Column.physical("d", DataTypes.FLOAT()), Column.physical("e", DataTypes.TINYINT().notNull()), Column.physical("f", DataTypes.DATE()), Column.physical("g", DataTypes.TIMESTAMP().notNull())), Collections.emptyList(), UniqueConstraint.primaryKey("name", Arrays.asList("a", "g")));
    GenericRowData rowData = GenericRowData.of(1L, 12345, StringData.fromString("ABCDE"), 12.12f, (byte) 2, 12345, TimestampData.fromLocalDateTime(LocalDateTime.parse("2012-12-12T12:12:12")));
    String index = "writing-documents";
    String myType = "MyType";
    Elasticsearch6DynamicSinkFactory sinkFactory = new Elasticsearch6DynamicSinkFactory();
    SinkFunctionProvider sinkRuntimeProvider = (SinkFunctionProvider) sinkFactory.createDynamicTableSink(context().withSchema(schema).withOption(ElasticsearchConnectorOptions.INDEX_OPTION.key(), index).withOption(ElasticsearchConnectorOptions.DOCUMENT_TYPE_OPTION.key(), myType).withOption(ElasticsearchConnectorOptions.HOSTS_OPTION.key(), elasticsearchContainer.getHttpHostAddress()).withOption(ElasticsearchConnectorOptions.FLUSH_ON_CHECKPOINT_OPTION.key(), "false").build()).getSinkRuntimeProvider(new MockContext());
    SinkFunction<RowData> sinkFunction = sinkRuntimeProvider.createSinkFunction();
    StreamExecutionEnvironment environment = StreamExecutionEnvironment.getExecutionEnvironment();
    environment.setParallelism(4);
    rowData.setRowKind(RowKind.UPDATE_AFTER);
    environment.<RowData>fromElements(rowData).addSink(sinkFunction);
    environment.execute();
    RestHighLevelClient client = getClient();
    Map<String, Object> response = client.get(new GetRequest(index, myType, "1_2012-12-12T12:12:12"), RequestOptions.DEFAULT).getSource();
    Map<Object, Object> expectedMap = new HashMap<>();
    expectedMap.put("a", 1);
    expectedMap.put("b", "00:00:12");
    expectedMap.put("c", "ABCDE");
    expectedMap.put("d", 12.12d);
    expectedMap.put("e", 2);
    expectedMap.put("f", "2003-10-20");
    expectedMap.put("g", "2012-12-12 12:12:12");
    assertThat(response, equalTo(expectedMap));
}

