@Test
public void testJdbcValidation() {
    // only password, no username
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("password", "pass");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "Either all or none of the following options should be provided:\n" + "username\npassword").isPresent());
    }
    // read partition properties not complete
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("scan.partition.column", "aaa");
        properties.put("scan.partition.lower-bound", "-10");
        properties.put("scan.partition.upper-bound", "100");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "Either all or none of the following options should be provided:\n" + "scan.partition.column\n" + "scan.partition.num\n" + "scan.partition.lower-bound\n" + "scan.partition.upper-bound").isPresent());
    }
    // read partition lower-bound > upper-bound
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("scan.partition.column", "aaa");
        properties.put("scan.partition.lower-bound", "100");
        properties.put("scan.partition.upper-bound", "-10");
        properties.put("scan.partition.num", "10");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "'scan.partition.lower-bound'='100' must not be larger than " + "'scan.partition.upper-bound'='-10'.").isPresent());
    }
    // lookup cache properties not complete
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("lookup.cache.max-rows", "10");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "Either all or none of the following options should be provided:\n" + "lookup.cache.max-rows\n" + "lookup.cache.ttl").isPresent());
    }
    // lookup cache properties not complete
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("lookup.cache.ttl", "1s");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "Either all or none of the following options should be provided:\n" + "lookup.cache.max-rows\n" + "lookup.cache.ttl").isPresent());
    }
    // lookup retries shouldn't be negative
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("lookup.max-retries", "-1");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "The value of 'lookup.max-retries' option shouldn't be negative, but is -1.").isPresent());
    }
    // sink retries shouldn't be negative
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("sink.max-retries", "-1");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "The value of 'sink.max-retries' option shouldn't be negative, but is -1.").isPresent());
    }
    // connection.max-retry-timeout shouldn't be smaller than 1 second
    try {
        Map<String, String> properties = getAllOptions();
        properties.put("connection.max-retry-timeout", "100ms");
        createTableSource(SCHEMA, properties);
        fail("exception expected");
    } catch (Throwable t) {
        assertTrue(ExceptionUtils.findThrowableWithMessage(t, "The value of 'connection.max-retry-timeout' option must be in second granularity and shouldn't be smaller than 1 second, but is 100ms.").isPresent());
    }
}

