@Test
public void testInsert() throws Exception {
    long started = System.currentTimeMillis();
    LOG.info("Test insert for {}", dbEnv);
    int elementsPerSource = 50;
    int numElementsPerCheckpoint = 7;
    int minElementsPerFailure = numElementsPerCheckpoint / 3;
    int maxElementsPerFailure = numElementsPerCheckpoint * 3;
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(dbEnv.getParallelism());
    env.setRestartStrategy(fixedDelayRestart(Integer.MAX_VALUE, Time.milliseconds(100)));
    env.setStreamTimeCharacteristic(TimeCharacteristic.ProcessingTime);
    env.enableCheckpointing(50, CheckpointingMode.EXACTLY_ONCE);
    // timeout checkpoints as some tasks may fail while triggering
    env.getCheckpointConfig().setCheckpointTimeout(1000);
    // NOTE: keep operator chaining enabled to prevent memory exhaustion by sources while maps
    // are still initializing
    env.addSource(new TestEntrySource(elementsPerSource, numElementsPerCheckpoint)).setParallelism(dbEnv.getParallelism()).map(new FailingMapper(minElementsPerFailure, maxElementsPerFailure)).addSink(JdbcSink.exactlyOnceSink(String.format(INSERT_TEMPLATE, INPUT_TABLE), JdbcITCase.TEST_ENTRY_JDBC_STATEMENT_BUILDER, JdbcExecutionOptions.builder().withMaxRetries(0).build(), JdbcExactlyOnceOptions.builder().withTransactionPerConnection(true).build(), this.dbEnv.getDataSourceSupplier()));
    env.execute();
    List<Integer> insertedIds = getInsertedIds(dbEnv.getContainer().getJdbcUrl(), dbEnv.getContainer().getUsername(), dbEnv.getContainer().getPassword(), INPUT_TABLE);
    List<Integer> expectedIds = IntStream.range(0, elementsPerSource * dbEnv.getParallelism()).boxed().collect(Collectors.toList());
    assertTrue(insertedIds.toString(), insertedIds.size() == expectedIds.size() && expectedIds.containsAll(insertedIds));
    LOG.info("Test insert for {} finished in {} ms.", dbEnv, System.currentTimeMillis() - started);
}

