@Test
public void testKafkaSourceSink() throws Exception {
    // we always use a different topic name for each parameterized topic,
    // in order to make sure the topic can be created.
    final String topic = "tstopic_" + format;
    createTestTopic(topic, 1, 1);
    // ---------- Produce an event time stream into Kafka -------------------
    String groupId = getStandardProps().getProperty("group.id");
    String bootstraps = getBootstrapServers();
    final String createTable = String.format("create table kafka (\n" + "  `computed-price` as price + 1.0,\n" + "  price decimal(38, 18),\n" + "  currency string,\n" + "  log_date date,\n" + "  log_time time(3),\n" + "  log_ts timestamp(3),\n" + "  ts as log_ts + INTERVAL '1' SECOND,\n" + "  watermark for ts as ts\n" + ") with (\n" + "  'connector' = '%s',\n" + "  'topic' = '%s',\n" + "  'properties.bootstrap.servers' = '%s',\n" + "  'properties.group.id' = '%s',\n" + "  'scan.startup.mode' = 'earliest-offset',\n" + "  %s\n" + ")", KafkaDynamicTableFactory.IDENTIFIER, topic, bootstraps, groupId, formatOptions());
    tEnv.executeSql(createTable);
    String initialValues = "INSERT INTO kafka\n" + "SELECT CAST(price AS DECIMAL(10, 2)), currency, " + " CAST(d AS DATE), CAST(t AS TIME(0)), CAST(ts AS TIMESTAMP(3))\n" + "FROM (VALUES (2.02,'Euro','2019-12-12', '00:00:01', '2019-12-12 00:00:01.001001'), \n" + "  (1.11,'US Dollar','2019-12-12', '00:00:02', '2019-12-12 00:00:02.002001'), \n" + "  (50,'Yen','2019-12-12', '00:00:03', '2019-12-12 00:00:03.004001'), \n" + "  (3.1,'Euro','2019-12-12', '00:00:04', '2019-12-12 00:00:04.005001'), \n" + "  (5.33,'US Dollar','2019-12-12', '00:00:05', '2019-12-12 00:00:05.006001'), \n" + "  (0,'DUMMY','2019-12-12', '00:00:10', '2019-12-12 00:00:10'))\n" + "  AS orders (price, currency, d, t, ts)";
    tEnv.executeSql(initialValues).await();
    // ---------- Consume stream from Kafka -------------------
    String query = "SELECT\n" + "  CAST(TUMBLE_END(ts, INTERVAL '5' SECOND) AS VARCHAR),\n" + "  CAST(MAX(log_date) AS VARCHAR),\n" + "  CAST(MAX(log_time) AS VARCHAR),\n" + "  CAST(MAX(ts) AS VARCHAR),\n" + "  COUNT(*),\n" + "  CAST(MAX(price) AS DECIMAL(10, 2))\n" + "FROM kafka\n" + "GROUP BY TUMBLE(ts, INTERVAL '5' SECOND)";
    DataStream<RowData> result = tEnv.toAppendStream(tEnv.sqlQuery(query), RowData.class);
    TestingSinkFunction sink = new TestingSinkFunction(2);
    result.addSink(sink).setParallelism(1);
    try {
        env.execute("Job_2");
    } catch (Throwable e) {
        // we have to use a specific exception to indicate the job is finished,
        // because the registered Kafka source is infinite.
        if (!isCausedByJobFinished(e)) {
            // re-throw
            throw e;
        }
    }
    List<String> expected = Arrays.asList("+I(2019-12-12 00:00:05.000,2019-12-12,00:00:03,2019-12-12 00:00:04.004,3,50.00)", "+I(2019-12-12 00:00:10.000,2019-12-12,00:00:05,2019-12-12 00:00:06.006,2,5.33)");
    assertEquals(expected, TestingSinkFunction.rows);
    // ------------- cleanup -------------------
    deleteTestTopic(topic);
}

@Test
public void testKafkaTableWithMultipleTopics() throws Exception {
    // ---------- create source and sink tables -------------------
    String tableTemp = "create table %s (\n" + "  currency string\n" + ") with (\n" + "  'connector' = '%s',\n" + "  'topic' = '%s',\n" + "  'properties.bootstrap.servers' = '%s',\n" + "  'properties.group.id' = '%s',\n" + "  'scan.startup.mode' = 'earliest-offset',\n" + "  %s\n" + ")";
    String groupId = getStandardProps().getProperty("group.id");
    String bootstraps = getBootstrapServers();
    List<String> currencies = Arrays.asList("Euro", "Dollar", "Yen", "Dummy");
    List<String> topics = currencies.stream().map(currency -> String.format("%s_%s", currency, format)).collect(Collectors.toList());
    // Because kafka connector currently doesn't support write data into multiple topic
    // together,
    // we have to create multiple sink tables.
    IntStream.range(0, 4).forEach(index -> {
        createTestTopic(topics.get(index), 1, 1);
        tEnv.executeSql(String.format(tableTemp, currencies.get(index).toLowerCase(), KafkaDynamicTableFactory.IDENTIFIER, topics.get(index), bootstraps, groupId, formatOptions()));
    });
    // create source table
    tEnv.executeSql(String.format(tableTemp, "currencies_topic_list", KafkaDynamicTableFactory.IDENTIFIER, String.join(";", topics), bootstraps, groupId, formatOptions()));
    // ---------- Prepare data in Kafka topics -------------------
    String insertTemp = "INSERT INTO %s\n" + "SELECT currency\n" + " FROM (VALUES ('%s'))\n" + " AS orders (currency)";
    currencies.forEach(currency -> {
        try {
            tEnv.executeSql(String.format(insertTemp, currency.toLowerCase(), currency)).await();
        } catch (Exception e) {
            fail(e.getMessage());
        }
    });
    // ------------- test the topic-list kafka source -------------------
    DataStream<RowData> result = tEnv.toAppendStream(tEnv.sqlQuery("SELECT currency FROM currencies_topic_list"), RowData.class);
    // expect to receive 4 records
    TestingSinkFunction sink = new TestingSinkFunction(4);
    result.addSink(sink);
    try {
        env.execute("Job_3");
    } catch (Throwable e) {
        // we have to use a specific exception to indicate the job is finished,
        // because the registered Kafka source is infinite.
        if (!isCausedByJobFinished(e)) {
            // re-throw
            throw e;
        }
    }
    List<String> expected = Arrays.asList("+I(Dollar)", "+I(Dummy)", "+I(Euro)", "+I(Yen)");
    TestingSinkFunction.rows.sort(Comparator.naturalOrder());
    assertEquals(expected, TestingSinkFunction.rows);
    // ------------- cleanup -------------------
    topics.forEach(super::deleteTestTopic);
}

