@Test
public void testKafkaTemporalJoinChangelog() throws Exception {
    // Set the session time zone to UTC, because the next `METADATA FROM
    // 'value.source.timestamp'` DDL
    // will use the session time zone when convert the changelog time from milliseconds to
    // timestamp
    tEnv.getConfig().set(TableConfigOptions.LOCAL_TIME_ZONE, "UTC");
    // we always use a different topic name for each parameterized topic,
    // in order to make sure the topic can be created.
    final String orderTopic = "temporal_join_topic_order_" + format;
    createTestTopic(orderTopic, 1, 1);
    final String productTopic = "temporal_join_topic_product_" + format;
    createTestTopic(productTopic, 1, 1);
    // ---------- Produce an event time stream into Kafka -------------------
    String groupId = getStandardProps().getProperty("group.id");
    String bootstraps = getBootstrapServers();
    // create order table and set initial values
    final String orderTableDDL = String.format("CREATE TABLE ordersTable (\n" + "  order_id STRING,\n" + "  product_id STRING,\n" + "  order_time TIMESTAMP(3),\n" + "  quantity INT,\n" + "  purchaser STRING,\n" + "  WATERMARK FOR order_time AS order_time - INTERVAL '1' SECOND\n" + ") WITH (\n" + "  'connector' = 'kafka',\n" + "  'topic' = '%s',\n" + "  'scan.startup.mode' = 'earliest-offset',\n" + "  'properties.bootstrap.servers' = '%s',\n" + "  'properties.group.id' = '%s',\n" + "  'format' = '%s'\n" + ")", orderTopic, bootstraps, groupId, format);
    tEnv.executeSql(orderTableDDL);
    String orderInitialValues = "INSERT INTO ordersTable\n" + "VALUES\n" + "('o_001', 'p_001', TIMESTAMP '2020-10-01 00:01:00', 1, 'Alice')," + "('o_002', 'p_002', TIMESTAMP '2020-10-01 00:02:00', 1, 'Bob')," + "('o_003', 'p_001', TIMESTAMP '2020-10-01 12:00:00', 2, 'Tom')," + "('o_004', 'p_002', TIMESTAMP '2020-10-01 12:00:00', 2, 'King')," + "('o_005', 'p_001', TIMESTAMP '2020-10-01 18:00:00', 10, 'Leonard')," + "('o_006', 'p_002', TIMESTAMP '2020-10-01 18:00:00', 10, 'Leonard')," + // used to advance watermark
    "('o_007', 'p_002', TIMESTAMP '2020-10-01 18:00:01', 10, 'Robinson')";
    tEnv.executeSql(orderInitialValues).await();
    // create product table and set initial values
    final String productTableDDL = String.format("CREATE TABLE productChangelogTable (\n" + "  product_id STRING,\n" + "  product_name STRING,\n" + "  product_price DECIMAL(10, 4),\n" + "  update_time TIMESTAMP(3) METADATA FROM 'value.source.timestamp' VIRTUAL,\n" + "  PRIMARY KEY(product_id) NOT ENFORCED,\n" + "  WATERMARK FOR update_time AS update_time - INTERVAL '1' SECOND\n" + ") WITH (\n" + "  'connector' = 'kafka',\n" + "  'topic' = '%s',\n" + "  'scan.startup.mode' = 'earliest-offset',\n" + "  'properties.bootstrap.servers' = '%s',\n" + "  'properties.group.id' = '%s',\n" + "  'value.format' = 'debezium-json'\n" + ")", productTopic, bootstraps, groupId);
    tEnv.executeSql(productTableDDL);
    // use raw format to initial the changelog data
    initialProductChangelog(productTopic, bootstraps);
    // ---------- query temporal join result from Kafka -------------------
    final List<String> result = collectRows(tEnv.sqlQuery("SELECT" + "  order_id," + "  order_time," + "  P.product_id," + "  P.update_time as product_update_time," + "  product_price," + "  purchaser," + "  product_name," + "  quantity," + "  quantity * product_price AS order_amount " + "FROM ordersTable AS O " + "LEFT JOIN productChangelogTable FOR SYSTEM_TIME AS OF O.order_time AS P " + "ON O.product_id = P.product_id"), 6).stream().map(row -> row.toString()).sorted().collect(Collectors.toList());
