@Test
public void testWriteData() throws Exception {
    final MockedSinkWriter writer = new MockedSinkWriter();
    final ReducingUpsertWriter<?> bufferedWriter = createBufferedWriter(writer);
    // write 4 records which doesn't trigger batch size
    writeData(bufferedWriter, new ReusableIterator(0, 4));
    assertTrue(writer.rowDataCollectors.isEmpty());
    // write one more record, and should flush the buffer
    writeData(bufferedWriter, new ReusableIterator(7, 1));
    HashMap<Integer, List<RowData>> expected = new HashMap<>();
    expected.put(1001, Collections.singletonList(GenericRowData.ofKind(UPDATE_AFTER, 1001, StringData.fromString("Java public for dummies"), StringData.fromString("Tan Ah Teck"), 11.11, 11, TimestampData.fromInstant(Instant.parse("2021-03-30T15:00:00Z")))));
    expected.put(1002, Collections.singletonList(GenericRowData.ofKind(UPDATE_AFTER, 1002, StringData.fromString("More Java for dummies"), StringData.fromString("Tan Ah Teck"), 22.22, 22, TimestampData.fromInstant(Instant.parse("2021-03-30T16:00:00Z")))));
    expected.put(1004, Collections.singletonList(GenericRowData.ofKind(UPDATE_AFTER, 1004, StringData.fromString("A Teaspoon of Java"), StringData.fromString("Kevin Jones"), 55.55, 55, TimestampData.fromInstant(Instant.parse("2021-03-30T18:00:00Z")))));
    expected.put(1005, Collections.singletonList(GenericRowData.ofKind(DELETE, 1005, StringData.fromString("A Teaspoon of Java 1.8"), StringData.fromString("Kevin Jones"), null, 1010, TimestampData.fromInstant(Instant.parse("2021-03-30T21:00:00Z")))));
    compareCompactedResult(expected, writer.rowDataCollectors);
    writer.rowDataCollectors.clear();
    // write remaining data, and they are still buffered
    writeData(bufferedWriter, new ReusableIterator(4, 3));
    assertTrue(writer.rowDataCollectors.isEmpty());
}

@Test
public void testFlushDataWhenCheckpointing() throws Exception {
