    }
}

@ParameterizedTest
@EnumSource(value = SubscriptionType.class, names = { "Failover", "Shared" })
void discoverPartitionsPeriodically(SubscriptionType subscriptionType) throws Throwable {
    String dynamicTopic = randomAlphabetic(10);
    Set<String> prexistingTopics = setupPreexistingTopics();
    Set<String> topicsToSubscribe = new HashSet<>(prexistingTopics);
    topicsToSubscribe.add(dynamicTopic);
    try (MockSplitEnumeratorContext<PulsarPartitionSplit> context = new MockSplitEnumeratorContext<>(NUM_SUBTASKS);
        PulsarSourceEnumerator enumerator = createEnumerator(subscriptionType, topicsToSubscribe, context, ENABLE_PERIODIC_PARTITION_DISCOVERY)) {
        testRegisterReadersForPreexistingTopics(subscriptionType, prexistingTopics, context, enumerator);
        // invoke partition discovery callable again and there should be no new assignments.
        runPeriodicPartitionDiscovery(context);
        int expectedSplitsAssignmentSequenceSize = subscriptionType == SubscriptionType.Failover ? 1 : 2;
        assertThat(context.getSplitsAssignmentSequence()).as("No new assignments should be made because there is no partition change").hasSize(expectedSplitsAssignmentSequenceSize);
        // create the dynamic topic.
        operator().createTopic(dynamicTopic, PulsarRuntimeOperator.DEFAULT_PARTITIONS);
        // invoke partition discovery callable again.
        while (true) {
            runPeriodicPartitionDiscovery(context);
            if (context.getSplitsAssignmentSequence().size() < 2) {
                sleepUninterruptibly(10, TimeUnit.MILLISECONDS);
            } else {
                break;
            }
        }
        verifyLastReadersAssignments(subscriptionType, context, Collections.singleton(dynamicTopic), expectedSplitsAssignmentSequenceSize + 1);
    }
}

@ParameterizedTest
@EnumSource(value = SubscriptionType.class, names = { "Failover", "Shared" })
void addSplitsBack(SubscriptionType subscriptionType) throws Throwable {
    Set<String> prexistingTopics = setupPreexistingTopics();
    try (MockSplitEnumeratorContext<PulsarPartitionSplit> context = new MockSplitEnumeratorContext<>(NUM_SUBTASKS);
        PulsarSourceEnumerator enumerator = createEnumerator(subscriptionType, prexistingTopics, context, ENABLE_PERIODIC_PARTITION_DISCOVERY)) {
        testRegisterReadersForPreexistingTopics(subscriptionType, prexistingTopics, context, enumerator);
        // Simulate a reader failure.
        context.unregisterReader(READER0);
        enumerator.addSplitsBack(context.getSplitsAssignmentSequence().get(0).assignment().get(READER0), READER0);
        int expectedSplitsAssignmentSequenceSize = subscriptionType == SubscriptionType.Failover ? 1 : 2;
        assertThat(context.getSplitsAssignmentSequence()).as("The added back splits should have not been assigned").hasSize(expectedSplitsAssignmentSequenceSize);
        // Simulate a reader recovery.
        registerReader(context, enumerator, READER0);
        verifyLastReadersAssignments(subscriptionType, context, prexistingTopics, expectedSplitsAssignmentSequenceSize + 1);
    }
}

