@Test
void testUploadBatchSizes() throws Exception {
    int numWriters = 5, numUploads = 5;
    ChangelogStorageMetricGroup metrics = new ChangelogStorageMetricGroup(createUnregisteredTaskManagerJobMetricGroup());
    Path basePath = Path.fromLocalFile(tempFolder.toFile());
    StateChangeFsUploader uploader = new StateChangeFsUploader(basePath, basePath.getFileSystem(), false, 100, metrics, TaskChangelogRegistry.NO_OP);
    ManuallyTriggeredScheduledExecutorService scheduler = new ManuallyTriggeredScheduledExecutorService();
    BatchingStateChangeUploadScheduler batcher = new BatchingStateChangeUploadScheduler(Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE, RetryPolicy.NONE, uploader, scheduler, new RetryingExecutor(1, metrics.getAttemptsPerUpload(), metrics.getTotalAttemptsPerUpload()), metrics);
    FsStateChangelogStorage storage = new FsStateChangelogStorage(batcher, Integer.MAX_VALUE, TaskChangelogRegistry.NO_OP);
    FsStateChangelogWriter[] writers = new FsStateChangelogWriter[numWriters];
    for (int i = 0; i < numWriters; i++) {
        writers[i] = storage.createWriter(Integer.toString(i), EMPTY_KEY_GROUP_RANGE, new SyncMailboxExecutor());
    }
    try {
        for (int upload = 0; upload < numUploads; upload++) {
            for (int writer = 0; writer < numWriters; writer++) {
                // with all thresholds on MAX and manually triggered executor, this shouldn't
                // cause actual uploads
                SequenceNumber from = writers[writer].nextSequenceNumber();
                writers[writer].append(0, new byte[] { 0, 1, 2, 3 });
                writers[writer].persist(from);
            }
            // now the uploads should be grouped and executed at once
            scheduler.triggerScheduledTasks();
        }
        assertThat(metrics.getUploadBatchSizes().getStatistics().getMin()).isEqualTo(numWriters);
        assertThat(metrics.getUploadBatchSizes().getStatistics().getMax()).isEqualTo(numWriters);
    } finally {
        storage.close();
    }
}

