@Test
void testVarLenCountEncoding() {
    try {
        long[] values = new long[] { 0, 1, 2, 3, 4, 0, 574, 45236, 0, 234623462, 23462462346L, 0, 9734028767869761L, 0x7fffffffffffffffL };
        // write
        ByteArrayOutputStream baos = new ByteArrayOutputStream(512);
        {
            DataOutputStream dataOut = new DataOutputStream(baos);
            for (long val : values) {
                DataOutputEncoder.writeVarLongCount(dataOut, val);
            }
            dataOut.flush();
            dataOut.close();
        }
        // read
        {
            ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
            DataInputStream dataIn = new DataInputStream(bais);
            for (long val : values) {
                long read = DataInputDecoder.readVarLongCount(dataIn);
                assertThat(read).withFailMessage("Wrong var-len encoded value read.").isEqualTo(val);
            }
        }
    } catch (Exception e) {
        System.err.println(e.getMessage());
        e.printStackTrace();
        fail("Test failed due to an exception: " + e.getMessage());
    }
}

