@Test
public void testSerializeDeserialize() throws Exception {
    testNullableField(BIGINT(), "null", null);
    testNullableField(STRING(), "null", null);
    testNullableField(STRING(), "\"This is a test.\"", "This is a test.");
    testNullableField(STRING(), "\"This is a test\n\r.\"", "This is a test\n\r.");
    testNullableField(BOOLEAN(), "true", true);
    testNullableField(BOOLEAN(), "null", null);
    testNullableField(TINYINT(), "124", (byte) 124);
    testNullableField(SMALLINT(), "10000", (short) 10000);
    testNullableField(INT(), "1234567", 1234567);
    testNullableField(BIGINT(), "12345678910", 12345678910L);
    testNullableField(FLOAT(), "0.33333334", 0.33333334f);
    testNullableField(DOUBLE(), "0.33333333332", 0.33333333332d);
    testNullableField(DECIMAL(38, 25), "\"1234.0000000000000000000000001\"", new BigDecimal("1234.0000000000000000000000001"));
    testNullableField(DECIMAL(38, 0), "\"123400000000000000000000000001\"", new BigDecimal("123400000000000000000000000001"));
    testNullableField(DATE(), "2018-10-12", Date.valueOf("2018-10-12"));
    testNullableField(TIME(0), "12:12:12", Time.valueOf("12:12:12"));
    testNullableField(TIMESTAMP(0), "\"2018-10-12 12:12:12\"", LocalDateTime.parse("2018-10-12T12:12:12"));
    testNullableField(TIMESTAMP(0), "\"2018-10-12 12:12:12.123\"", LocalDateTime.parse("2018-10-12T12:12:12.123"));
    testNullableField(TIMESTAMP_LTZ(0), "\"1970-01-01 00:02:03Z\"", Instant.ofEpochSecond(123));
    testNullableField(TIMESTAMP_LTZ(0), "\"1970-01-01 00:02:03.456Z\"", Instant.ofEpochMilli(123456));
    testNullableField(ROW(FIELD("f0", STRING()), FIELD("f1", INT()), FIELD("f2", BOOLEAN())), "Hello;42;false", Row.of("Hello", 42, false));
    testNullableField(ARRAY(STRING()), "a;b;c", new String[] { "a", "b", "c" });
    testNullableField(ARRAY(TINYINT()), "12;4;null", new Byte[] { 12, 4, null });
    testNullableField(BYTES(), "awML", new byte[] { 107, 3, 11 });
    testNullableField(TIME(3), "12:12:12.232", LocalTime.parse("12:12:12.232"));
    testNullableField(TIME(2), "12:12:12.23", LocalTime.parse("12:12:12.23"));
    testNullableField(TIME(1), "12:12:12.2", LocalTime.parse("12:12:12.2"));
    testNullableField(TIME(0), "12:12:12", LocalTime.parse("12:12:12"));
}

@Test
public void testSerializeDeserializeCustomizedProperties() throws Exception {
    Consumer<CsvRowDataSerializationSchema.Builder> serConfig = (serSchemaBuilder) -> serSchemaBuilder.setEscapeCharacter('*').setQuoteCharacter('\'').setArrayElementDelimiter(":").setFieldDelimiter(';');
    Consumer<CsvRowDataDeserializationSchema.Builder> deserConfig = (deserSchemaBuilder) -> deserSchemaBuilder.setEscapeCharacter('*').setQuoteCharacter('\'').setArrayElementDelimiter(":").setFieldDelimiter(';');
    testFieldDeserialization(STRING(), "123*'4**", "123'4*", deserConfig, ";");
    testField(STRING(), "'123''4**'", "'123''4**'", serConfig, deserConfig, ";");
    testFieldDeserialization(STRING(), "'a;b*'c'", "a;b'c", deserConfig, ";");
    testField(STRING(), "'a;b''c'", "a;b'c", serConfig, deserConfig, ";");
    testFieldDeserialization(INT(), "       12          ", 12, deserConfig, ";");
    testField(INT(), "12", 12, serConfig, deserConfig, ";");
    testFieldDeserialization(ROW(FIELD("f0", STRING()), FIELD("f1", STRING())), "1:hello", Row.of("1", "hello"), deserConfig, ";");
    testField(ROW(FIELD("f0", STRING()), FIELD("f1", STRING())), "'1:hello'", Row.of("1", "hello"), serConfig, deserConfig, ";");
    testField(ROW(FIELD("f0", STRING()), FIELD("f1", STRING())), "'1:hello world'", Row.of("1", "hello world"), serConfig, deserConfig, ";");
    testField(STRING(), "null", "null", serConfig, deserConfig, // string because null literal has not been set
    ";");
    testFieldDeserialization(TIME(3), "12:12:12.232", LocalTime.parse("12:12:12.232"), deserConfig, ";");
    testFieldDeserialization(TIME(3), "12:12:12.232342", LocalTime.parse("12:12:12.232"), deserConfig, ";");
    testFieldDeserialization(TIME(3), "12:12:12.23", LocalTime.parse("12:12:12.23"), deserConfig, ";");
    testFieldDeserialization(TIME(2), "12:12:12.23", LocalTime.parse("12:12:12.23"), deserConfig, ";");
    testFieldDeserialization(TIME(2), "12:12:12.232312", LocalTime.parse("12:12:12.23"), deserConfig, ";");
    testFieldDeserialization(TIME(2), "12:12:12.2", LocalTime.parse("12:12:12.2"), deserConfig, ";");
    testFieldDeserialization(TIME(1), "12:12:12.2", LocalTime.parse("12:12:12.2"), deserConfig, ";");
    testFieldDeserialization(TIME(1), "12:12:12.2235", LocalTime.parse("12:12:12.2"), deserConfig, ";");
    testFieldDeserialization(TIME(1), "12:12:12", LocalTime.parse("12:12:12"), deserConfig, ";");
    testFieldDeserialization(TIME(0), "12:12:12", LocalTime.parse("12:12:12"), deserConfig, ";");
    testFieldDeserialization(TIME(0), "12:12:12.45", LocalTime.parse("12:12:12"), deserConfig, ";");
    int precision = 5;
    try {
        testFieldDeserialization(TIME(precision), "12:12:12.45", LocalTime.parse("12:12:12"), deserConfig, ";");
        fail();
    } catch (Exception e) {
        assertEquals("Csv does not support TIME type with precision: 5, it only supports precision 0 ~ 3.", e.getMessage());
    }
}

