@Test
public void testPendingFileRecoverableSerializer() throws IOException {
    HadoopPathBasedPendingFileRecoverable recoverable = new HadoopPathBasedPendingFileRecoverable(new Path("hdfs://fake/path"), new Path("hdfs://fake/path.inprogress.uuid"));
    HadoopPathBasedPendingFileRecoverableSerializer serializer = new HadoopPathBasedPendingFileRecoverableSerializer();
    byte[] serializedBytes = serializer.serialize(recoverable);
    HadoopPathBasedPendingFileRecoverable deSerialized = serializer.deserialize(serializer.getVersion(), serializedBytes);
    assertEquals(recoverable.getTargetFilePath(), deSerialized.getTargetFilePath());
    assertEquals(recoverable.getTempFilePath(), deSerialized.getTempFilePath());
}

