    TestStreamingFileSinkFactory<String> streamingFileSinkFactory = new TestStreamingFileSinkFactory<>();
    stream.addSink(streamingFileSinkFactory.createSink(builder, 1000));
    env.execute();
    validateResult(data, configuration, basePath);
}

