    check("select x, y from orcFilterTable where (d is not null and y > 26) or (d is null and x = 'x3')", Arrays.asList(Row.of("x3", "3"), Row.of("x27", "27")));
    check("select x, y from orcFilterTable where e = 3.1400 or x = 'x10'", Arrays.asList(Row.of("x1", "1"), Row.of("x10", "10")));
    check("select x, y from orcFilterTable where f = date '2020-01-01' and x = 'x1'", Collections.singletonList(Row.of("x1", "1")));
