    try {
        tupleDs.first(1);
    } catch (Exception e) {
        Assert.fail();
    }
    // should work
    try {
        tupleDs.first(10);
    } catch (Exception e) {
        Assert.fail();
    }
    // should not work n == 0
    try {
        tupleDs.first(0);
        Assert.fail();
    } catch (InvalidProgramException ipe) {
