/**
 * Tests that we can concurrently serialize and access the ParameterTool. See FLINK-7943
 */
@Test
public void testConcurrentExecutionConfigSerialization() throws ExecutionException, InterruptedException {
    final int numInputs = 10;
    Collection<String> input = new ArrayList<>(numInputs);
    for (int i = 0; i < numInputs; i++) {
        input.add("--" + UUID.randomUUID());
        input.add(UUID.randomUUID().toString());
    }
    final String[] args = input.toArray(new String[0]);
    final ParameterTool parameterTool = (ParameterTool) createParameterToolFromArgs(args);
    final int numThreads = 5;
    final int numSerializations = 100;
    final Collection<CompletableFuture<Void>> futures = new ArrayList<>(numSerializations);
    final ExecutorService executorService = Executors.newFixedThreadPool(numThreads);
    try {
        for (int i = 0; i < numSerializations; i++) {
            futures.add(CompletableFuture.runAsync(() -> {
                try {
                    serializeDeserialize(parameterTool);
                } catch (Exception e) {
                    throw new CompletionException(e);
                }
            }, executorService));
        }
        for (CompletableFuture<Void> future : futures) {
            future.get();
        }
    } finally {
        executorService.shutdownNow();
        executorService.awaitTermination(1000L, TimeUnit.MILLISECONDS);
    }
}

@Test
public void testGenerate() {
    final String fileA = "fileA";
    final String fileB = "fileB";
    final Map<String, DistributedCache.DistributedCacheEntry> originalArtifacts = Stream.of(Tuple2.of(fileA, new DistributedCache.DistributedCacheEntry("test1", true)), Tuple2.of(fileB, new DistributedCache.DistributedCacheEntry("test2", false))).collect(Collectors.toMap(x -> x.f0, x -> x.f1));
    final ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(10);
    env.registerCachedFile("test1", fileA, true);
    env.registerCachedFile("test2", fileB, false);
    env.fromElements(1, 3, 5).map((MapFunction<Integer, String>) value -> String.valueOf(value + 1)).writeAsText("/tmp/csv");
    final Plan generatedPlanUnderTest = env.createProgramPlan("test");
    final Map<String, DistributedCache.DistributedCacheEntry> retrievedArtifacts = generatedPlanUnderTest.getCachedFiles().stream().collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    assertEquals(1, generatedPlanUnderTest.getDataSinks().size());
    assertEquals(10, generatedPlanUnderTest.getDefaultParallelism());
    assertEquals(env.getConfig(), generatedPlanUnderTest.getExecutionConfig());
    assertEquals("test", generatedPlanUnderTest.getJobName());
    assertEquals(originalArtifacts.size(), retrievedArtifacts.size());
    assertEquals(originalArtifacts.get(fileA), retrievedArtifacts.get(fileA));
    assertEquals(originalArtifacts.get(fileB), retrievedArtifacts.get(fileB));
}

