@Test
void testRecoverFromSavepoint() throws Exception {
    Path stateBackend1 = Files.createDirectory(temporaryPath.resolve("stateBackend1"));
    final JobGraph jobGraph = createJobGraph(stateBackend1.toFile());
    clusterClient.submitJob(jobGraph).get(TestingUtils.infiniteTime().toMilliseconds(), TimeUnit.MILLISECONDS);
    // Wait until all tasks running and getting a successful savepoint
    CommonTestUtils.waitUntilCondition(() -> triggerSavepoint(clusterClient, jobGraph.getJobID(), savepointPath) != null, 1000);
    // Trigger savepoint 2
    final String savepoint2Path = triggerSavepoint(clusterClient, jobGraph.getJobID(), savepointPath);
    // Cancel the old job
    clusterClient.cancel(jobGraph.getJobID());
    CommonTestUtils.waitUntilCondition(() -> clusterClient.getJobStatus(jobGraph.getJobID()).get() == JobStatus.CANCELED, 1000);
    // Start a new job with savepoint 2
    Path stateBackend2 = Files.createDirectory(temporaryPath.resolve("stateBackend2"));
    final JobGraph jobGraphWithSavepoint = createJobGraph(stateBackend2.toFile());
    final JobID jobId = jobGraphWithSavepoint.getJobID();
    jobGraphWithSavepoint.setSavepointRestoreSettings(SavepointRestoreSettings.forPath(savepoint2Path));
    clusterClient.submitJob(jobGraphWithSavepoint).get(TIMEOUT, TimeUnit.MILLISECONDS);
    assertThat(clusterClient.requestJobResult(jobId).join().isSuccess()).isTrue();
}

@Test
void testLeaderElectionAndRetrieval() throws Exception {
    final String configMapName = LEADER_CONFIGMAP_NAME + System.currentTimeMillis();
    KubernetesLeaderElectionDriver leaderElectionDriver = null;
    KubernetesLeaderRetrievalDriver leaderRetrievalDriver = null;
    final FlinkKubeClient flinkKubeClient = kubernetesExtension.getFlinkKubeClient();
    final Configuration configuration = kubernetesExtension.getConfiguration();
    final String clusterId = configuration.getString(KubernetesConfigOptions.CLUSTER_ID);
    final KubernetesConfigMapSharedWatcher configMapSharedWatcher = flinkKubeClient.createConfigMapSharedWatcher(KubernetesUtils.getConfigMapLabels(clusterId, LABEL_CONFIGMAP_TYPE_HIGH_AVAILABILITY));
    final ExecutorService watchExecutorService = Executors.newCachedThreadPool();
    final TestingLeaderElectionEventHandler electionEventHandler = new TestingLeaderElectionEventHandler(LEADER_ADDRESS);
    try {
        leaderElectionDriver = new KubernetesLeaderElectionDriver(flinkKubeClient, configMapSharedWatcher, watchExecutorService, new KubernetesLeaderElectionConfiguration(configMapName, UUID.randomUUID().toString(), configuration), electionEventHandler, electionEventHandler::handleError);
        electionEventHandler.init(leaderElectionDriver);
        final TestingLeaderRetrievalEventHandler retrievalEventHandler = new TestingLeaderRetrievalEventHandler();
        leaderRetrievalDriver = new KubernetesLeaderRetrievalDriver(flinkKubeClient, configMapSharedWatcher, watchExecutorService, configMapName, retrievalEventHandler, KubernetesUtils::getLeaderInformationFromConfigMap, retrievalEventHandler::handleError);
        electionEventHandler.waitForLeader();
        // Check the new leader is confirmed
        final LeaderInformation confirmedLeaderInformation = electionEventHandler.getConfirmedLeaderInformation();
        assertThat(confirmedLeaderInformation.getLeaderAddress()).isEqualTo(LEADER_ADDRESS);
        // Check the leader retrieval driver should be notified the leader address
        retrievalEventHandler.waitForNewLeader();
        assertThat(retrievalEventHandler.getLeaderSessionID()).isEqualByComparingTo(confirmedLeaderInformation.getLeaderSessionID());
        assertThat(retrievalEventHandler.getAddress()).isEqualTo(confirmedLeaderInformation.getLeaderAddress());
    } finally {
        electionEventHandler.close();
        if (leaderElectionDriver != null) {
            leaderElectionDriver.close();
        }
        if (leaderRetrievalDriver != null) {
            leaderRetrievalDriver.close();
        }
        flinkKubeClient.deleteConfigMap(configMapName).get();
        configMapSharedWatcher.close();
        ExecutorUtils.gracefulShutdown(5, TimeUnit.SECONDS, watchExecutorService);
    }
}

