@Test
void testReleaseAndTryRemoveIsIdempotent() throws Exception {
    new Context() {

        {
            runTest(() -> {
                leaderCallbackGrantLeadership();
                final KubernetesStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> store = new KubernetesStateHandleStore<>(flinkKubeClient, LEADER_CONFIGMAP_NAME, longStateStorage, filter, LOCK_IDENTITY);
                final RuntimeException discardException = new RuntimeException("Test exception.");
                store.addAndLock(key, new TestingLongStateHandleHelper.LongStateHandle(2L, discardIdx -> {
                    if (discardIdx == 0) {
                        throw discardException;
                    }
                }));
                assertThat(store.getAllAndLock()).hasSize(1);
                assertThat(store.getAndLock(key)).isNotNull();
                // First remove attempt should fail when we're discarding the underlying
                // state.
                assertThatThrownBy(() -> store.releaseAndTryRemove(key)).satisfies(anyCauseMatches(discardException.getClass(), discardException.getMessage()));
                // Now we should see that the node is "soft-deleted". This means it can
                // no longer be accessed by the get methods, but the underlying state
                // still exists.
                assertThat(store.getAllAndLock()).hasSize(0);
                assertThatThrownBy(() -> store.getAndLock(key));
                assertThat(TestingLongStateHandleHelper.getGlobalDiscardCount()).isEqualTo(0);
                assertThat(getLeaderConfigMap().getData().containsKey(key)).isTrue();
                // Second retry should succeed and remove the underlying state and the
                // reference in config map.
                assertThat(store.releaseAndTryRemove(key)).isTrue();
                assertThat(store.getAllAndLock()).hasSize(0);
                assertThatThrownBy(() -> store.getAndLock(key));
                assertThat(TestingLongStateHandleHelper.getGlobalDiscardCount()).isEqualTo(1);
                assertThat(getLeaderConfigMap().getData().containsKey(key)).isFalse();
            });
        }
    };
}

@Test
void testReleaseAndTryRemoveAllIsIdempotent() throws Exception {
    new Context() {

        {
            runTest(() -> {
                leaderCallbackGrantLeadership();
                final KubernetesStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> store = new KubernetesStateHandleStore<>(flinkKubeClient, LEADER_CONFIGMAP_NAME, longStateStorage, filter, LOCK_IDENTITY);
                final int numKeys = 10;
                final RuntimeException discardException = new RuntimeException("Test exception.");
                final List<TestingLongStateHandleHelper.LongStateHandle> states = new ArrayList<>();
                for (int idx = 0; idx < numKeys; idx++) {
                    final boolean failFirstDiscard = idx % 2 == 0;
                    final TestingLongStateHandleHelper.LongStateHandle state = new TestingLongStateHandleHelper.LongStateHandle(idx + 1, discardIdx -> {
                        if (failFirstDiscard && discardIdx == 0) {
                            throw discardException;
                        }
                    });
                    states.add(state);
                    store.addAndLock(key + "_" + idx, state);
                }
                // All keys should be retrievable
                assertThat(store.getAllAndLock()).hasSize(numKeys);
                for (int idx = 0; idx < numKeys; idx++) {
                    assertThat(store.getAndLock(key + "_" + idx)).isNotNull();
                }
                // First remove attempt should fail when we're discarding the underlying
                // state.
                assertThatThrownBy(store::releaseAndTryRemoveAll).satisfies(anyCauseMatches(discardException.getClass(), discardException.getMessage()));
                // Now we should see that the all nodes are "soft-deleted". This means
                // it can no longer be accessed by the get methods, but the underlying
                // state still exists.
                assertThat(store.getAllAndLock()).hasSize(0);
                for (int idx = 0; idx < numKeys; idx++) {
                    final String indexKey = key + "_" + idx;
                    assertThatThrownBy(() -> store.getAndLock(indexKey));
                    assertThat(getLeaderConfigMap().getData()).containsKey(indexKey);
                }
                // Half of the state handles should have been discarded.
                assertThat(states.stream().filter(TestingLongStateHandleHelper.LongStateHandle::isDiscarded)).hasSize(numKeys / 2);
                // Second retry should succeed and remove the underlying state and the
                // reference in config map.
                store.releaseAndTryRemoveAll();
                assertThat(store.getAllAndLock()).hasSize(0);
                for (int idx = 0; idx < numKeys; idx++) {
                    final String indexKey = key + "_" + idx;
                    assertThatThrownBy(() -> store.getAndLock(indexKey));
                    assertThat(getLeaderConfigMap().getData()).doesNotContainKey(indexKey);
                }
                // All handles should have been discarded.
                assertThat(states.stream().filter(TestingLongStateHandleHelper.LongStateHandle::isDiscarded)).hasSize(numKeys);
            });
        }
    };
}

