    typeInformationTypeNameMap.put(BasicTypeInfo.CHAR_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.CHAR);
    typeInformationTypeNameMap.put(BasicTypeInfo.FLOAT_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.FLOAT);
    typeInformationTypeNameMap.put(BasicTypeInfo.DOUBLE_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.DOUBLE);
    typeInformationTypeNameMap.put(BasicTypeInfo.SHORT_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.SHORT);
    typeInformationTypeNameMap.put(BasicTypeInfo.LONG_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.LONG);
    typeInformationTypeNameMap.put(BasicTypeInfo.STRING_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.STRING);
    typeInformationTypeNameMap.put(BasicTypeInfo.BYTE_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.BYTE);
    typeInformationTypeNameMap.put(PickledByteArrayTypeInfo.PICKLED_BYTE_ARRAY_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.PICKLED_BYTES);
    typeInformationTypeNameMap.put(BasicTypeInfo.BOOLEAN_TYPE_INFO, FlinkFnApi.TypeInfo.TypeName.BOOLEAN);
    typeInformationTypeNameMap.put(SqlTimeTypeInfo.DATE, FlinkFnApi.TypeInfo.TypeName.SQL_DATE);
    typeInformationTypeNameMap.put(SqlTimeTypeInfo.TIME, FlinkFnApi.TypeInfo.TypeName.SQL_TIME);
    typeInformationTypeNameMap.put(SqlTimeTypeInfo.TIMESTAMP, FlinkFnApi.TypeInfo.TypeName.SQL_TIMESTAMP);
    for (Map.Entry<TypeInformation, FlinkFnApi.TypeInfo.TypeName> entry : typeInformationTypeNameMap.entrySet()) {
        assertEquals(entry.getValue(), PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(entry.getKey()).getTypeName());
    }
    TypeInformation primitiveIntegerArrayTypeInfo = PrimitiveArrayTypeInfo.INT_PRIMITIVE_ARRAY_TYPE_INFO;
    FlinkFnApi.TypeInfo convertedFieldType = PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(primitiveIntegerArrayTypeInfo);
    assertEquals(convertedFieldType.getTypeName(), FlinkFnApi.TypeInfo.TypeName.PRIMITIVE_ARRAY);
    assertEquals(convertedFieldType.getCollectionElementType().getTypeName(), FlinkFnApi.TypeInfo.TypeName.INT);
    TypeInformation basicIntegerArrayTypeInfo = BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO;
    FlinkFnApi.TypeInfo convertedBasicFieldType = PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(basicIntegerArrayTypeInfo);
    assertEquals(convertedBasicFieldType.getTypeName(), FlinkFnApi.TypeInfo.TypeName.BASIC_ARRAY);
    assertEquals(convertedBasicFieldType.getCollectionElementType().getTypeName(), FlinkFnApi.TypeInfo.TypeName.INT);
    TypeInformation objectArrayTypeInfo = Types.OBJECT_ARRAY(Types.ROW(Types.INT));
    FlinkFnApi.TypeInfo convertedTypeInfoProto = PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(objectArrayTypeInfo);
    assertEquals(convertedTypeInfoProto.getTypeName(), FlinkFnApi.TypeInfo.TypeName.OBJECT_ARRAY);
    assertEquals(convertedTypeInfoProto.getCollectionElementType().getTypeName(), FlinkFnApi.TypeInfo.TypeName.ROW);
    assertEquals(convertedTypeInfoProto.getCollectionElementType().getRowTypeInfo().getFields(0).getFieldType().getTypeName(), FlinkFnApi.TypeInfo.TypeName.INT);
    TypeInformation rowTypeInfo = Types.ROW(Types.INT);
    convertedFieldType = PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(rowTypeInfo);
    assertEquals(convertedFieldType.getTypeName(), FlinkFnApi.TypeInfo.TypeName.ROW);
    assertEquals(convertedFieldType.getRowTypeInfo().getFields(0).getFieldType().getTypeName(), FlinkFnApi.TypeInfo.TypeName.INT);
    TypeInformation tupleTypeInfo = Types.TUPLE(Types.INT);
    convertedFieldType = PythonTypeUtils.TypeInfoToProtoConverter.toTypeInfoProto(tupleTypeInfo);
    assertEquals(convertedFieldType.getTypeName(), FlinkFnApi.TypeInfo.TypeName.TUPLE);
    assertEquals(convertedFieldType.getTupleTypeInfo().getFieldTypes(0).getTypeName(), FlinkFnApi.TypeInfo.TypeName.INT);
}

