/**
 * Tests that when the onStop future completes that no other messages will be processed.
 */
@Test
void testOnStopFutureCompletionDirectlyTerminatesAkkaRpcActor() throws Exception {
    final CompletableFuture<Void> onStopFuture = new CompletableFuture<>();
    final TerminatingAfterOnStopFutureCompletionEndpoint endpoint = new TerminatingAfterOnStopFutureCompletionEndpoint(akkaRpcService, onStopFuture);
    try {
        endpoint.start();
        final AsyncOperationGateway asyncOperationGateway = endpoint.getSelfGateway(AsyncOperationGateway.class);
        final CompletableFuture<Void> terminationFuture = endpoint.closeAsync();
        assertThat(terminationFuture).isNotDone();
        final CompletableFuture<Integer> firstAsyncOperationFuture = asyncOperationGateway.asyncOperation(Time.fromDuration(timeout));
        final CompletableFuture<Integer> secondAsyncOperationFuture = asyncOperationGateway.asyncOperation(Time.fromDuration(timeout));
        endpoint.awaitEnterAsyncOperation();
        // complete stop operation which should prevent the second async operation from being
        // executed
        onStopFuture.complete(null);
        // we can only complete the termination after the first async operation has been
        // completed
        assertThat(terminationFuture).isNotDone();
        endpoint.triggerUnblockAsyncOperation();
        assertThat(firstAsyncOperationFuture.get()).isEqualTo(42);
        terminationFuture.get();
        assertThat(endpoint.getNumberAsyncOperationCalls()).isEqualTo(1);
        assertThat(secondAsyncOperationFuture).failsWithin(timeout).withThrowableOfType(ExecutionException.class).withCauseInstanceOf(RecipientUnreachableException.class);
    } finally {
        RpcUtils.terminateRpcEndpoint(endpoint);
    }
}

