@Test
public void testBlobServerRetainsJobs() throws Exception {
    final JobID jobId1 = new JobID();
    final JobID jobId2 = new JobID();
    final byte[] fileContent = { 1, 2, 3, 4 };
    final PermanentBlobKey blobKey1 = TestingBlobUtils.writePermanentBlob(temporaryFolder.toPath(), jobId1, fileContent);
    final PermanentBlobKey blobKey2 = TestingBlobUtils.writePermanentBlob(temporaryFolder.toPath(), jobId2, fileContent);
    final ExecutorService executorService = Executors.newSingleThreadExecutor();
    try (final BlobServer blobServer = createTestInstance(temporaryFolder.getAbsolutePath(), BlobServerOptions.CLEANUP_INTERVAL.defaultValue())) {
        blobServer.retainJobs(Collections.singleton(jobId1), executorService);
        assertThat(blobServer.getFile(jobId1, blobKey1)).hasBinaryContent(fileContent);
        assertThatThrownBy(() -> blobServer.getFile(jobId2, blobKey2)).isInstanceOf(NoSuchFileException.class);
    } finally {
        assertThat(executorService.shutdownNow()).isEmpty();
    }
}

