    assertEquals(rescalingDescriptor(to(0, 1), array(mappings(to(0, 2), to(1))), set(1)), getAssignedState(vertices.get(operatorIds.get(1)), operatorIds.get(1), 0).getInputRescalingDescriptor());
    assertEquals(rescalingDescriptor(to(1, 2), array(mappings(to(0, 2), to(1))), set(1)), getAssignedState(vertices.get(operatorIds.get(1)), operatorIds.get(1), 1).getInputRescalingDescriptor());
