    client.delete().forPath(childNodePath);
    counter.shutdown(JobStatus.FINISHED).join();
    assertThat(client.checkExists().forPath(counterNodePath)).as("A retry of the shutdown should have worked now after the root cause was resolved.").isNull();
}

