@Test
public void testFinalizeIsCalledUponSuccess() throws Exception {
    final JobVertex vertex1 = spy(new JobVertex("test vertex 1"));
    vertex1.setInvokableClass(NoOpInvokable.class);
    vertex1.setParallelism(3);
    final JobVertex vertex2 = spy(new JobVertex("test vertex 2"));
    vertex2.setInvokableClass(NoOpInvokable.class);
    vertex2.setParallelism(2);
    final SchedulerBase scheduler = createScheduler(JobGraphTestUtils.streamingJobGraph(vertex1, vertex2), ComponentMainThreadExecutorServiceAdapter.forMainThread(), EXECUTOR_RESOURCE.getExecutor());
    scheduler.startScheduling();
    final ExecutionGraph eg = scheduler.getExecutionGraph();
    assertEquals(JobStatus.RUNNING, eg.getState());
    ExecutionGraphTestUtils.switchAllVerticesToRunning(eg);
    // move all vertices to finished state
    ExecutionGraphTestUtils.finishAllVertices(eg);
    assertEquals(JobStatus.FINISHED, eg.waitUntilTerminal());
    verify(vertex1, times(1)).finalizeOnMaster(any(ClassLoader.class));
    verify(vertex2, times(1)).finalizeOnMaster(any(ClassLoader.class));
    assertEquals(0, eg.getRegisteredExecutions().size());
}

@Test
public void testFinalizeIsNotCalledUponFailure() throws Exception {
    final JobVertex vertex = spy(new JobVertex("test vertex 1"));
    vertex.setInvokableClass(NoOpInvokable.class);
    vertex.setParallelism(1);
    final SchedulerBase scheduler = createScheduler(JobGraphTestUtils.streamingJobGraph(vertex), ComponentMainThreadExecutorServiceAdapter.forMainThread(), EXECUTOR_RESOURCE.getExecutor());
    scheduler.startScheduling();
    final ExecutionGraph eg = scheduler.getExecutionGraph();
    assertEquals(JobStatus.RUNNING, eg.getState());
    ExecutionGraphTestUtils.switchAllVerticesToRunning(eg);
    // fail the execution
    final Execution exec = eg.getJobVertex(vertex.getID()).getTaskVertices()[0].getCurrentExecutionAttempt();
    exec.fail(new Exception("test"));
    assertEquals(JobStatus.FAILED, eg.waitUntilTerminal());
    verify(vertex, times(0)).finalizeOnMaster(any(ClassLoader.class));
    assertEquals(0, eg.getRegisteredExecutions().size());
}

@Test
public void testPipelinedPartitionConsumable() throws Exception {
    IntermediateResult result = createResult(ResultPartitionType.PIPELINED, 2);
    IntermediateResultPartition partition1 = result.getPartitions()[0];
    IntermediateResultPartition partition2 = result.getPartitions()[1];
    // Not consumable on init
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    // Partition 1 consumable after data are produced
    partition1.markDataProduced();
    assertTrue(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    // Not consumable if failover happens
    result.resetForNewExecution();
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
}

@Test
public void testBlockingPartitionConsumable() throws Exception {
    IntermediateResult result = createResult(ResultPartitionType.BLOCKING, 2);
    IntermediateResultPartition partition1 = result.getPartitions()[0];
    IntermediateResultPartition partition2 = result.getPartitions()[1];
    ConsumedPartitionGroup consumedPartitionGroup = partition1.getConsumedPartitionGroups().get(0);
    // Not consumable on init
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
    // Not consumable if only one partition is FINISHED
    partition1.markFinished();
    assertTrue(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
    // Consumable after all partitions are FINISHED
    partition2.markFinished();
    assertTrue(partition1.isConsumable());
    assertTrue(partition2.isConsumable());
    assertTrue(consumedPartitionGroup.areAllPartitionsFinished());
    // Not consumable if failover happens
    result.resetForNewExecution();
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
}

@Test
public void testBlockingPartitionResetting() throws Exception {
    IntermediateResult result = createResult(ResultPartitionType.BLOCKING, 2);
    IntermediateResultPartition partition1 = result.getPartitions()[0];
    IntermediateResultPartition partition2 = result.getPartitions()[1];
    ConsumedPartitionGroup consumedPartitionGroup = partition1.getConsumedPartitionGroups().get(0);
    // Not consumable on init
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    // Not consumable if partition1 is FINISHED
    partition1.markFinished();
    assertEquals(1, consumedPartitionGroup.getNumberOfUnfinishedPartitions());
    assertTrue(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
    // Reset the result and mark partition2 FINISHED, the result should still not be consumable
    result.resetForNewExecution();
    assertEquals(2, consumedPartitionGroup.getNumberOfUnfinishedPartitions());
    partition2.markFinished();
    assertEquals(1, consumedPartitionGroup.getNumberOfUnfinishedPartitions());
    assertFalse(partition1.isConsumable());
    assertTrue(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
    // Consumable after all partitions are FINISHED
    partition1.markFinished();
    assertEquals(0, consumedPartitionGroup.getNumberOfUnfinishedPartitions());
    assertTrue(partition1.isConsumable());
    assertTrue(partition2.isConsumable());
    assertTrue(consumedPartitionGroup.areAllPartitionsFinished());
    // Not consumable again if failover happens
    result.resetForNewExecution();
    assertEquals(2, consumedPartitionGroup.getNumberOfUnfinishedPartitions());
    assertFalse(partition1.isConsumable());
    assertFalse(partition2.isConsumable());
    assertFalse(consumedPartitionGroup.areAllPartitionsFinished());
}

