        closeableRegistry.registerCloseable((globalPool.createBufferPool(10, 30))::lazyDestroy);
        assertEquals(60, globalPool.getNumberOfRequestedMemorySegments());
        assertEquals(120, globalPool.getRequestedSegmentsUsage());
        assertThat(globalPool.getUsageWarning(), equalTo(Optional.of("Memory usage [120%] is too high to satisfy all of the requests. " + "This can severely impact network throughput. " + "Please consider increasing available network memory, " + "or decreasing configured size of network buffer pools. (" + "totalMemory=6.250kb (6400 bytes), " + "requestedMemory=7.500kb (7680 bytes), " + "missingMemory=1.250kb (1280 bytes))")));
        assertThat(globalPool.getUsageWarning(), equalTo(Optional.empty()));
        BufferPool bufferPool2 = globalPool.createBufferPool(10, 20);
        assertEquals(80, globalPool.getNumberOfRequestedMemorySegments());
        assertEquals(160, globalPool.getRequestedSegmentsUsage());
        assertThat(globalPool.getUsageWarning(), equalTo(Optional.of("Memory usage [160%] is too high to satisfy all of the requests. " + "This can severely impact network throughput. " + "Please consider increasing available network memory, " + "or decreasing configured size of network buffer pools. (" + "totalMemory=6.250kb (6400 bytes), " + "requestedMemory=10.000kb (10240 bytes), " + "missingMemory=3.750kb (3840 bytes))")));
        bufferPool2.lazyDestroy();
        bufferPool1.lazyDestroy();
        assertEquals(40, globalPool.getNumberOfRequestedMemorySegments());
        assertEquals(40 * 128, globalPool.getRequestedMemory());
        assertEquals(80, globalPool.getRequestedSegmentsUsage());
        assertThat(globalPool.getUsageWarning(), equalTo(Optional.of("Memory usage [80%] went back to normal")));
        assertThat(globalPool.getUsageWarning(), equalTo(Optional.empty()));
