@Test
public void testRecycleBufferForNotifyingSubpartitionView() throws Exception {
    final int numberOfBuffers = 2;
    try (final BoundedData data = createBoundedData()) {
        writeBuffers(data, numberOfBuffers);
        final VerifyNotificationResultSubpartitionView subpartitionView = new VerifyNotificationResultSubpartitionView();
        final BoundedData.Reader reader = data.createReader(subpartitionView);
        final Buffer buffer1 = reader.nextBuffer();
        final Buffer buffer2 = reader.nextBuffer();
        assertNotNull(buffer1);
        assertNotNull(buffer2);
        assertFalse(subpartitionView.isAvailable);
        buffer1.recycleBuffer();
        // the view is notified while recycling buffer if reader has not tagged finished
        assertTrue(subpartitionView.isAvailable);
        subpartitionView.resetAvailable();
        assertFalse(subpartitionView.isAvailable);
        // the next buffer is null to make reader tag finished
        assertNull(reader.nextBuffer());
        buffer2.recycleBuffer();
        // the view is not notified while recycling buffer if reader already finished
        assertFalse(subpartitionView.isAvailable);
    }
}

@Test
public void testRecycleBufferForNotifyingBufferAvailabilityListener() throws Exception {
    final ResultSubpartition subpartition = createFileBoundedBlockingSubpartition();
    final int numberOfBuffers = 2;
    writeBuffers(subpartition, numberOfBuffers);
    final VerifyNotificationBufferAvailabilityListener listener = new VerifyNotificationBufferAvailabilityListener();
    final ResultSubpartitionView subpartitionView = createView(subpartition, listener);
    assertFalse(listener.isAvailable);
    final BufferAndBacklog buffer1 = subpartitionView.getNextBuffer();
    final BufferAndBacklog buffer2 = subpartitionView.getNextBuffer();
    assertNotNull(buffer1);
    assertNotNull(buffer2);
    // the next buffer is null in view because FileBufferReader has no available buffers for
    // reading ahead
    assertFalse(subpartitionView.getAvailabilityAndBacklog(Integer.MAX_VALUE).isAvailable());
    // recycle a buffer to trigger notification of data available
    buffer1.buffer().recycleBuffer();
    assertTrue(listener.isAvailable);
    // cleanup
    buffer2.buffer().recycleBuffer();
    subpartitionView.releaseAllResources();
    subpartition.release();
}

@Test
public void testFairConsumptionLocalChannelsPreFilled() throws Exception {
    final int numberOfChannels = 37;
    final int buffersPerChannel = 27;
    PipelinedResultPartition[] resultPartitions = IntStream.range(0, numberOfChannels).mapToObj(i -> (PipelinedResultPartition) new ResultPartitionBuilder().build()).toArray(PipelinedResultPartition[]::new);
    final BufferConsumer bufferConsumer = createFilledFinishedBufferConsumer(42);
    // ----- create some source channels and fill them with buffers -----
    final PipelinedSubpartition[] sources = Arrays.stream(resultPartitions).map(resultPartition -> resultPartition.getAllPartitions()[0]).toArray(PipelinedSubpartition[]::new);
    for (final PipelinedSubpartition subpartition : sources) {
        for (int p = 0; p < buffersPerChannel; p++) {
            subpartition.add(bufferConsumer.copy());
        }
        subpartition.finish();
    }
    for (ResultPartition rp : resultPartitions) {
        rp.setup();
    }
    // ----- create reading side -----
    final SingleInputGate gate = createFairnessVerifyingInputGate(numberOfChannels);
    final InputChannel[] inputChannels = IntStream.range(0, numberOfChannels).mapToObj(i -> InputChannelBuilder.newBuilder().setChannelIndex(i).setPartitionManager(resultPartitions[i].partitionManager).setPartitionId(resultPartitions[i].getPartitionId()).buildLocalChannel(gate)).toArray(InputChannel[]::new);
    setupInputGate(gate, inputChannels);
    // read all the buffers and the EOF event
    for (int i = numberOfChannels * (buffersPerChannel + 1); i > 0; --i) {
        assertNotNull(gate.getNext());
        int min = Integer.MAX_VALUE;
        int max = 0;
        for (PipelinedSubpartition source : sources) {
            int size = source.getNumberOfQueuedBuffers();
            min = Math.min(min, size);
            max = Math.max(max, size);
        }
        assertTrue(max == min || max == (min + 1));
    }
    assertFalse(gate.getNext().isPresent());
}

