@Test
public void testDeclineCheckpointWithUserExceptionCanBeDeserializedWithoutUserClass() throws Exception {
    final String className = "UserException";
    final URLClassLoader userClassLoader = ClassLoaderUtils.compileAndLoadJava(TEMPORARY_FOLDER.newFolder(), className + ".java", String.format("public class %s extends RuntimeException { public %s() {super(\"UserMessage\");} }", className, className));
    Throwable userException = (Throwable) Class.forName(className, false, userClassLoader).newInstance();
    CheckpointException checkpointException = new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED, userException);
    final byte[] serializedCheckpointMessage = InstantiationUtil.serializeObject(new DeclineCheckpoint(new JobID(), new ExecutionAttemptID(), 1, checkpointException));
    final DeclineCheckpoint deserializedCheckpointMessage = InstantiationUtil.deserializeObject(serializedCheckpointMessage, ClassLoader.getSystemClassLoader());
    Throwable throwable = deserializedCheckpointMessage.getSerializedCheckpointException().unwrap();
    assertThat(throwable, instanceOf(CheckpointException.class));
    Optional<Throwable> throwableWithMessage = ExceptionUtils.findThrowableWithMessage(throwable, userException.getMessage());
    assertTrue(throwableWithMessage.isPresent());
    assertThat(throwableWithMessage.get().getMessage(), equalTo(userException.getMessage()));
}

