        ScheduledFuture<?> reportTask = Iterators.getOnlyElement(scheduledTasks.iterator());
        assertThat(reportTask.getDelay(TimeUnit.SECONDS)).isEqualTo(MetricOptions.REPORTER_INTERVAL.defaultValue().getSeconds());
    } finally {
        registry.shutdown().get();
    }
}

