        twoTimesElementSet.add(testElement.deepCopy());
    }
    InternalPriorityQueue<TestElement> priorityQueue = newPriorityQueue(1);
    priorityQueue.addAll(twoTimesElementSet);
    priorityQueue.addAll(elementSet);
