@Test
public void testFatalErrorAfterUnInterruptibleInvoke() throws Exception {
    final CompletableFuture<Throwable> fatalErrorFuture = new CompletableFuture<>();
    final TestingTaskManagerActions taskManagerActions = TestingTaskManagerActions.newBuilder().setNotifyFatalErrorConsumer((s, throwable) -> fatalErrorFuture.complete(throwable)).build();
    final Configuration config = new Configuration();
    config.setLong(TaskManagerOptions.TASK_CANCELLATION_TIMEOUT, 10);
    final Task task = createTaskBuilder().setInvokable(InvokableUnInterruptibleBlockingInvoke.class).setTaskManagerConfig(config).setTaskManagerActions(taskManagerActions).build(Executors.directExecutor());
    try {
        task.startTaskThread();
        awaitLatch.await();
        task.cancelExecution();
        // wait for the notification of notifyFatalError
        final Throwable fatalError = fatalErrorFuture.join();
        assertThat(fatalError, is(notNullValue()));
    } finally {
        // Interrupt again to clean up Thread
        triggerLatch.trigger();
        task.getExecutingThread().interrupt();
        task.getExecutingThread().join();
    }
}

