@Test
public void testDeclineCheckpoint() throws Exception {
    TestCheckpointResponder testCheckpointResponder = new TestCheckpointResponder();
    final Task task = createTaskBuilder().setInvokable(InvokableDeclingingCheckpoints.class).setCheckpointResponder(testCheckpointResponder).build(Executors.directExecutor());
    assertCheckpointDeclined(task, testCheckpointResponder, 1, CheckpointFailureReason.CHECKPOINT_DECLINED_TASK_NOT_READY);
    task.startTaskThread();
    try {
        awaitLatch.await();
        assertEquals(ExecutionState.RUNNING, task.getExecutionState());
        assertCheckpointDeclined(task, testCheckpointResponder, InvokableDeclingingCheckpoints.REJECTED_EXECUTION_CHECKPOINT_ID, CheckpointFailureReason.CHECKPOINT_DECLINED_TASK_CLOSING);
        assertCheckpointDeclined(task, testCheckpointResponder, InvokableDeclingingCheckpoints.THROWING_CHECKPOINT_ID, CheckpointFailureReason.TASK_FAILURE);
        assertCheckpointDeclined(task, testCheckpointResponder, InvokableDeclingingCheckpoints.TRIGGERING_FAILED_CHECKPOINT_ID, CheckpointFailureReason.TASK_FAILURE);
    } finally {
        triggerLatch.trigger();
        task.getExecutingThread().join();
    }
    assertEquals(ExecutionState.FINISHED, task.getTerminationFuture().getNow(null));
}

