/**
 * Tests that cached result is NOT reused after refresh interval.
 */
@Test
public void testCachedStatsUpdatedAfterRefreshInterval() throws Exception {
    final Duration shortRefreshInterval = Duration.ofMillis(1);
    // first entry is in the past, so refresh is triggered immediately upon fetching it
    final JobVertexThreadInfoStats initialThreadInfoStats = createThreadInfoStats(Instant.now().minus(10, ChronoUnit.SECONDS), REQUEST_ID, Duration.ofMillis(5), Collections.singletonList(threadInfoSample));
    final JobVertexThreadInfoStats threadInfoStatsAfterRefresh = createThreadInfoStats(1, TIME_GAP, Collections.singletonList(threadInfoSample));
    // register a CountDownLatch with the cache so we can await refresh of the entry
    CountDownLatch cacheRefreshed = new CountDownLatch(1);
    Cache<JobVertexThreadInfoTracker.Key, JobVertexThreadInfoStats> vertexStatsCache = createCache(CLEAN_UP_INTERVAL, new LatchRemovalListener<>(cacheRefreshed));
    final JobVertexThreadInfoTracker<JobVertexThreadInfoStats> tracker = createThreadInfoTracker(CLEAN_UP_INTERVAL, shortRefreshInterval, vertexStatsCache, initialThreadInfoStats, threadInfoStatsAfterRefresh);
    // no stats yet, but the request triggers async collection of stats
    assertFalse(tracker.getVertexStats(JOB_ID, EXECUTION_JOB_VERTEX).isPresent());
    // block until the async call completes and the first result is available
    tracker.getResultAvailableFuture().get();
    // retrieve the entry, triggering the refresh as side effect
    assertExpectedEqualsReceived(initialThreadInfoStats, tracker.getVertexStats(JOB_ID, EXECUTION_JOB_VERTEX));
    // wait until the entry is refreshed
    cacheRefreshed.await();
    // verify that we get the second result on the next request
    Optional<JobVertexThreadInfoStats> result = tracker.getVertexStats(JOB_ID, EXECUTION_JOB_VERTEX);
    assertExpectedEqualsReceived(threadInfoStatsAfterRefresh, result);
}

