@Test
public void testShutDown() throws Exception {
    Map<ExecutionAttemptID, CompletableFuture<TaskExecutorThreadInfoGateway>> executionWithGateways = createMockSubtaskWithGateways(CompletionType.SUCCESSFULLY, CompletionType.TIMEOUT);
    List<CompletableFuture<JobVertexThreadInfoStats>> requestFutures = new ArrayList<>();
    CompletableFuture<JobVertexThreadInfoStats> requestFuture1 = coordinator.triggerThreadInfoRequest(executionWithGateways, DEFAULT_NUMBER_OF_SAMPLES, DEFAULT_DELAY_BETWEEN_SAMPLES, DEFAULT_MAX_STACK_TRACE_DEPTH);
