    requestFutures.add(requestFuture1);
    requestFutures.add(requestFuture2);
    for (CompletableFuture<JobVertexThreadInfoStats> future : requestFutures) {
        assertFalse(future.isDone());
    }
    // shut down
    coordinator.shutDown();
    // verify all completed
    for (CompletableFuture<JobVertexThreadInfoStats> future : requestFutures) {
        assertTrue(future.isCompletedExceptionally());
    }
    // verify new trigger returns failed future
    CompletableFuture<JobVertexThreadInfoStats> future = coordinator.triggerThreadInfoRequest(executionWithGateways, DEFAULT_NUMBER_OF_SAMPLES, DEFAULT_DELAY_BETWEEN_SAMPLES, DEFAULT_MAX_STACK_TRACE_DEPTH);
