@Test
public void testRepeatableCleanupWithLockOnNode() throws Exception {
    final CuratorFramework client = ZooKeeperUtils.useNamespaceAndEnsurePath(ZOOKEEPER.getClient(), "/testRepeatableCleanupWithLockOnNode");
    final TestingLongStateHandleHelper storage = new TestingLongStateHandleHelper();
    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForCreation = new ZooKeeperStateHandleStore<>(client, storage);
    final ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> storeForDeletion = new ZooKeeperStateHandleStore<>(client, storage);
    final String pathInZooKeeper = "/testRepeatableCleanupWithLock";
    final long actualValue = 12345L;
    final RuntimeException expectedException = new RuntimeException("RuntimeException for testing the failing discardState call.");
    final TestingLongStateHandleHelper.LongStateHandle stateHandle = new TestingLongStateHandleHelper.LongStateHandle(actualValue, throwExceptionOnce(expectedException));
    final RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle> handleForCreation = storeForCreation.addAndLock(pathInZooKeeper, stateHandle);
    final RetrievableStateHandle<TestingLongStateHandleHelper.LongStateHandle> handleForDeletion = storeForDeletion.getAndLock(pathInZooKeeper);
    assertEquals(handleForCreation.retrieveState().getValue(), actualValue);
    assertEquals(handleForDeletion.retrieveState().getValue(), actualValue);
    assertFalse("Deletion by the first StateHandleStore shouldn't be successful because there's still a lock from StateHandleStore #1.", storeForCreation.releaseAndTryRemove(pathInZooKeeper));
    assertNotNull("StateHandle should not be marked for deletion, yet.", client.checkExists().forPath(ZooKeeperStateHandleStore.getRootLockPath(pathInZooKeeper)));
    assertNull("The lock for storeForCreation should have been removed", client.checkExists().forPath(storeForCreation.getInstanceLockPath(pathInZooKeeper)));
    assertEquals("discardState shouldn't have been called, yet.", 0, stateHandle.getNumberOfDiscardCalls());
    try {
        storeForDeletion.releaseAndTryRemove(pathInZooKeeper);
        fail("Exception should have been thrown.");
    } catch (Exception e) {
        ExceptionUtils.assertThrowable(e, expectedException::equals);
    }
    assertNull("StateHandle should be marked for deletion.", client.checkExists().forPath(ZooKeeperStateHandleStore.getRootLockPath(pathInZooKeeper)));
    assertNotNull("StateHandle should not be deleted, yet.", client.checkExists().forPath(pathInZooKeeper));
    assertFalse("The StateHandle should not be discarded, yet.", stateHandle.isDiscarded());
    assertTrue(storeForDeletion.releaseAndTryRemove(pathInZooKeeper));
    assertNull("The StateHandle node should have been removed", client.checkExists().forPath(pathInZooKeeper));
    assertTrue("The StateHandle should have been discarded.", stateHandle.isDiscarded());
}

