@Test
public void testReleaseAndTryRemoveAllRepeatableAfterFailure() throws Exception {
    // Setup
    final TestingLongStateHandleHelper stateHandleProvider = new TestingLongStateHandleHelper();
    ZooKeeperStateHandleStore<TestingLongStateHandleHelper.LongStateHandle> store = new ZooKeeperStateHandleStore<>(ZOOKEEPER.getClient(), stateHandleProvider);
    // Config
    final String pathInZooKeeper = "/testDiscardAllWithFailure";
    final long actualValue = 12345L;
    final RuntimeException expectedException = new RuntimeException("RuntimeException for testing the failing discardState call.");
    final TestingLongStateHandleHelper.LongStateHandle failingStateHandle = new TestingLongStateHandleHelper.LongStateHandle(actualValue, throwExceptionOnce(expectedException));
    store.addAndLock(pathInZooKeeper + "-with-failure", failingStateHandle);
    final TestingLongStateHandleHelper.LongStateHandle succeedingStateHandle = TestingLongStateHandleHelper.createState(42);
    store.addAndLock(pathInZooKeeper + "-without-failure", succeedingStateHandle);
    try {
        store.releaseAndTryRemoveAll();
        fail("An Exception should have been thrown.");
    } catch (Exception e) {
        ExceptionUtils.assertThrowable(e, expectedException::equals);
    }
    assertEquals("One discardState call should have failed resulting in one node being left, still.", 1, ZOOKEEPER.getClient().getChildren().forPath("/").size());
    assertEquals(0, failingStateHandle.getNumberOfSuccessfulDiscardCalls());
    assertEquals(1, failingStateHandle.getNumberOfDiscardCalls());
    assertEquals(1, succeedingStateHandle.getNumberOfSuccessfulDiscardCalls());
    store.releaseAndTryRemoveAll();
    assertTrue("The second removal attempt should have succeeded with no nodes left.", ZOOKEEPER.getClient().getChildren().forPath("/").isEmpty());
    assertEquals(1, failingStateHandle.getNumberOfSuccessfulDiscardCalls());
    assertEquals(2, failingStateHandle.getNumberOfDiscardCalls());
    assertEquals(1, succeedingStateHandle.getNumberOfSuccessfulDiscardCalls());
    assertEquals(1, succeedingStateHandle.getNumberOfDiscardCalls());
}

/**
