/**
 * Test that an upload is discarded only when it's not used by all backends for which it was
 * initiated.
 *
 * <p>Scenario:
 *
 * <ol>
 *   <li>Two backends start pre-emptive uploads, both go into the same file (StreamStateHandle)
 *   <li>First backend materializes (starts and finishes)
 *   <li>State should not be discarded
 *   <li>Second backend materializes (starts and finishes)
 *   <li>State should be discarded
 * </ol>
 */
@Test
public void testPreEmptiveUploadForMultipleBackends() throws Exception {
    // using the same range (rescaling not involved)
    final KeyGroupRange kgRange = KeyGroupRange.of(0, 10);
    final JobID jobId = new JobID();
    final ExecutionConfig cfg = new ExecutionConfig();
    final TaskChangelogRegistry registry = TaskChangelogRegistry.defaultChangelogRegistry(directExecutor());
    final TestingUploadScheduler scheduler = new TestingUploadScheduler(registry);
    final StateChangelogStorage<?> storage = new FsStateChangelogStorage(scheduler, 0, registry);
    final StateChangelogWriter<?> w1 = storage.createWriter("test-operator-1", kgRange, new SyncMailboxExecutor()), w2 = storage.createWriter("test-operator-2", kgRange, new SyncMailboxExecutor());
    try (ChangelogKeyedStateBackend<String> b1 = backend(jobId, kgRange, cfg, w1);
        ChangelogKeyedStateBackend<String> b2 = backend(jobId, kgRange, cfg, w2)) {
        changeAndLogRandomState(b1, scheduler.uploads::size);
        changeAndLogRandomState(b2, scheduler.uploads::size);
        // emulate sharing the same file
        final TestingStreamStateHandle handle = new TestingStreamStateHandle();
        scheduler.completeUploads(task -> uploadResult(task, () -> handle));
        truncate(w1, b1);
        assertRetained(singletonList(handle));
        truncate(w1, b2);
        assertDiscarded(singletonList(handle));
    }
}

/**
 * A basic test for appending the metadata on first state access.
 */
@Test
public void testMetadataOperationLogged() throws IOException {
    TestingStateChangelogWriter writer = new TestingStateChangelogWriter();
    InternalKeyContextImpl<String> keyContext = new InternalKeyContextImpl<>(KeyGroupRange.of(1, 1000), 1000);
    try (StateChangeLogger<String, Namespace> logger = getLogger(writer, keyContext)) {
        List<Tuple2<Integer, StateChangeOperation>> expectedAppends = new ArrayList<>();
        expectedAppends.add(Tuple2.of(COMMON_KEY_GROUP, METADATA));
        // log every applicable operations, several times each
        int numOpTypes = StateChangeOperation.values().length;
        for (int i = 0; i < numOpTypes * 7; i++) {
            String element = Integer.toString(i);
            StateChangeOperation operation = StateChangeOperation.byCode((byte) (i % numOpTypes));
            log(operation, element, logger, keyContext).ifPresent(expectedAppends::add);
        }
        assertEquals(expectedAppends, writer.appends);
    }
}

