@Test
public void testSanityCheckArenaBlockSize() {
    long testWriteBufferSize = 56 * 1024 * 1024L;
    long testDefaultArenaSize = RocksDBMemoryControllerUtils.calculateRocksDBDefaultArenaBlockSize(testWriteBufferSize);
    long testWriteBufferCapacityBoundary = testDefaultArenaSize * 8 / 7;
    assertThat("The sanity check should pass with default arena block size", RocksDBOperationUtils.sanityCheckArenaBlockSize(testWriteBufferSize, 0, testWriteBufferCapacityBoundary), is(true));
    assertThat("The sanity check should pass with default arena block size given as argument", RocksDBOperationUtils.sanityCheckArenaBlockSize(testWriteBufferSize, testDefaultArenaSize, testWriteBufferCapacityBoundary), is(true));
    assertThat("The sanity check should pass when the configured arena block size is smaller than the boundary.", RocksDBOperationUtils.sanityCheckArenaBlockSize(testWriteBufferSize, testDefaultArenaSize - 1, testWriteBufferCapacityBoundary), is(true));
    assertThat("The sanity check should fail when the configured arena block size is higher than the boundary.", RocksDBOperationUtils.sanityCheckArenaBlockSize(testWriteBufferSize, testDefaultArenaSize + 1, testWriteBufferCapacityBoundary), is(false));
}

