    final StreamGraph streamGraph = buildGraph(TestSink.newBuilder().setDefaultCommitter().setDefaultGlobalCommitter().build(), runtimeExecutionMode);
    final StreamNode sourceNode = findNodeName(streamGraph, node -> node.contains("Source"));
    final StreamNode writerNode = findWriter(streamGraph);
    final StreamNode committerNode = findCommitter(streamGraph);
    validateTopology(sourceNode, IntSerializer.class, writerNode, SinkWriterOperatorFactory.class, PARALLELISM, -1);
    StreamNode lastNode;
    if (runtimeExecutionMode == RuntimeExecutionMode.STREAMING) {
        // in streaming writer and committer are merged into one operator
        assertThat(streamGraph.getStreamNodes().size(), equalTo(4));
    } else {
        assertThat(streamGraph.getStreamNodes().size(), equalTo(4));
        validateTopology(writerNode, SimpleVersionedSerializerTypeSerializerProxy.class, committerNode, CommitterOperatorFactory.class, PARALLELISM, -1);
    }
    lastNode = committerNode;
    final StreamNode globalCommitterNode = findGlobalCommitter(streamGraph);
    validateTopology(lastNode, SimpleVersionedSerializerTypeSerializerProxy.class, globalCommitterNode, SimpleOperatorFactory.class, 1, 1);
}

/**
 * It is not possible anymore with Sink V2 to have a topology consisting only of Sink Writer and
 * a Global Committer. The SinkV1Adapter translates these topologies into a Sink Writer, an only
 * forwarding committer and the Global Committer.
 */
@Test
public void generateWriterGlobalCommitterTopology() {
    final StreamGraph streamGraph = buildGraph(TestSink.newBuilder().setCommittableSerializer(TestSink.StringCommittableSerializer.INSTANCE).setGlobalCommittableSerializer(TestSink.StringCommittableSerializer.INSTANCE).setDefaultGlobalCommitter().build(), runtimeExecutionMode);
    final StreamNode sourceNode = findNodeName(streamGraph, node -> node.contains("Source"));
    final StreamNode writerNode = findWriter(streamGraph);
    validateTopology(sourceNode, IntSerializer.class, writerNode, SinkWriterOperatorFactory.class, PARALLELISM, -1);
    final StreamNode committerNode = findCommitter(streamGraph);
    final StreamNode globalCommitterNode = findGlobalCommitter(streamGraph);
    validateTopology(writerNode, SimpleVersionedSerializerTypeSerializerProxy.class, committerNode, CommitterOperatorFactory.class, PARALLELISM, -1);
    validateTopology(committerNode, SimpleVersionedSerializerTypeSerializerProxy.class, globalCommitterNode, SimpleOperatorFactory.class, 1, 1);
}

