@Test
public void testServerFailure() throws Exception {
    CollectSinkOperatorCoordinator coordinator = new CollectSinkOperatorCoordinator(SOCKET_TIMEOUT_MILLIS);
    coordinator.start();
    List<List<Row>> expected = Arrays.asList(Arrays.asList(Row.of(1, "aaa"), Row.of(2, "bbb")), Arrays.asList(Row.of(3, "ccc"), Row.of(4, "ddd"), Row.of(5, "eee")));
    ServerThread server = new ServerThread(expected, 3);
    server.start();
    coordinator.handleEventFromOperator(0, new CollectSinkAddressEvent(server.getServerAddress()));
    // a normal response
    CollectCoordinationRequest request = new CollectCoordinationRequest("version1", 123);
    CollectCoordinationResponse response = (CollectCoordinationResponse) coordinator.handleCoordinationRequest(request).get();
    assertResponseEquals(request, response, 0, expected.get(0));
    // a normal response
    request = new CollectCoordinationRequest("version2", 456);
    response = (CollectCoordinationResponse) coordinator.handleCoordinationRequest(request).get();
    assertResponseEquals(request, response, 0, expected.get(1));
    // server closes here
    request = new CollectCoordinationRequest("version3", 789);
    CompletableFuture<CoordinationResponse> responseFuture = coordinator.handleCoordinationRequest(request);
    coordinator.subtaskFailed(0, null);
    // new server comes
    expected = Collections.singletonList(Arrays.asList(Row.of(6, "fff"), Row.of(7, "ggg")));
    server = new ServerThread(expected, 2);
    server.start();
    coordinator.handleEventFromOperator(0, new CollectSinkAddressEvent(server.getServerAddress()));
    // check failed request
    response = (CollectCoordinationResponse) responseFuture.get();
    assertResponseEquals(request, response, -1, Collections.emptyList());
    // a normal response
    request = new CollectCoordinationRequest("version4", 101112);
    response = (CollectCoordinationResponse) coordinator.handleCoordinationRequest(request).get();
    assertResponseEquals(request, response, 0, expected.get(0));
    server.close();
    coordinator.close();
}

