/**
 * Verify ContinuousProcessingTimeTrigger fire.
 */
@Test
public void testWindowFiring() throws Exception {
    ContinuousProcessingTimeTrigger<TimeWindow> trigger = ContinuousProcessingTimeTrigger.of(Time.milliseconds(5));
    assertTrue(trigger.canMerge());
    ListStateDescriptor<Integer> stateDesc = new ListStateDescriptor<>("window-contents", BasicTypeInfo.INT_TYPE_INFO.createSerializer(new ExecutionConfig()));
    WindowOperator<Byte, Integer, Iterable<Integer>, WindowedInteger, TimeWindow> operator = new WindowOperator<>(TumblingProcessingTimeWindows.of(Time.milliseconds(10)), new TimeWindow.Serializer(), new NullByteKeySelector<>(), BasicTypeInfo.BYTE_TYPE_INFO.createSerializer(new ExecutionConfig()), stateDesc, new InternalIterableWindowFunction<>(new IntegerSumWindowFunction()), trigger, 0, null);
    KeyedOneInputStreamOperatorTestHarness<Byte, Integer, WindowedInteger> testHarness = new KeyedOneInputStreamOperatorTestHarness<>(operator, operator.getKeySelector(), BasicTypeInfo.BYTE_TYPE_INFO);
    ArrayDeque<Object> expectedOutput = new ArrayDeque<>();
    testHarness.open();
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(0);
    testHarness.processElement(1, NO_TIMESTAMP);
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(2);
    testHarness.processElement(2, NO_TIMESTAMP);
    // Fire window [0, 10), value is 1+2=3.
    testHarness.getProcessingTimeService().setCurrentTime(5);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 10), 3), 9));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(7);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [0, 10), value is 3+3=6.
    testHarness.getProcessingTimeService().setCurrentTime(9);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 10), 6), 9));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [10, 20)
    testHarness.getProcessingTimeService().setCurrentTime(10);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [10, 20), value is 3.
    testHarness.getProcessingTimeService().setCurrentTime(15);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(10, 20), 3), 19));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // window [10, 20)
    testHarness.getProcessingTimeService().setCurrentTime(18);
    testHarness.processElement(3, NO_TIMESTAMP);
    // Fire window [10, 20), value is 3+3=6.
    testHarness.getProcessingTimeService().setCurrentTime(20);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(10, 20), 6), 19));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
}

@Test
public void testMergingWindows() throws Exception {
    ContinuousProcessingTimeTrigger<TimeWindow> trigger = ContinuousProcessingTimeTrigger.of(Time.milliseconds(5));
    assertTrue(trigger.canMerge());
    ListStateDescriptor<Integer> stateDesc = new ListStateDescriptor<>("window-contents", BasicTypeInfo.INT_TYPE_INFO.createSerializer(new ExecutionConfig()));
    WindowOperator<Byte, Integer, Iterable<Integer>, WindowedInteger, TimeWindow> operator = new WindowOperator<>(ProcessingTimeSessionWindows.withGap(Time.milliseconds(10)), new TimeWindow.Serializer(), new NullByteKeySelector<>(), BasicTypeInfo.BYTE_TYPE_INFO.createSerializer(new ExecutionConfig()), stateDesc, new InternalIterableWindowFunction<>(new IntegerSumWindowFunction()), trigger, 0, null);
    KeyedOneInputStreamOperatorTestHarness<Byte, Integer, WindowedInteger> testHarness = new KeyedOneInputStreamOperatorTestHarness<>(operator, operator.getKeySelector(), BasicTypeInfo.BYTE_TYPE_INFO);
    ArrayDeque<Object> expectedOutput = new ArrayDeque<>();
    testHarness.open();
    // window [0, 10)
    testHarness.getProcessingTimeService().setCurrentTime(0);
    testHarness.processElement(1, NO_TIMESTAMP);
    // window [2, 12) ==> [0, 12)
    testHarness.getProcessingTimeService().setCurrentTime(2);
    testHarness.processElement(2, NO_TIMESTAMP);
    // Merged timer should still fire.
    testHarness.getProcessingTimeService().setCurrentTime(5);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 12), 3), 11));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // Merged window should work as normal.
    testHarness.getProcessingTimeService().setCurrentTime(9);
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    testHarness.getProcessingTimeService().setCurrentTime(10);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 12), 3), 11));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // Firing on time.
    testHarness.getProcessingTimeService().setCurrentTime(15);
    expectedOutput.add(new StreamRecord<>(new WindowedInteger(new TimeWindow(0, 12), 3), 11));
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
    // Window is dropped already.
    testHarness.getProcessingTimeService().setCurrentTime(100);
    TestHarnessUtil.assertOutputEquals("Output mismatch", expectedOutput, testHarness.getOutput());
}

/**
 * Verify that state of separate windows does not leak into other windows.
 */
@Test
public void testWindowSeparationAndFiring() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(CountTrigger.<TimeWindow>of(3), new TimeWindow.Serializer());
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(2, 4)));
    // shouldn't have any timers
    assertEquals(0, testHarness.numProcessingTimeTimers());
    assertEquals(0, testHarness.numEventTimeTimers());
    assertEquals(2, testHarness.numStateEntries());
    assertEquals(1, testHarness.numStateEntries(new TimeWindow(0, 2)));
    assertEquals(1, testHarness.numStateEntries(new TimeWindow(2, 4)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.FIRE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(2, 4)));
    // right now, CountTrigger will clear it's state in onElement when firing
    // ideally, this should be moved to onFire()
    assertEquals(1, testHarness.numStateEntries());
    assertEquals(0, testHarness.numStateEntries(new TimeWindow(0, 2)));
    assertEquals(1, testHarness.numStateEntries(new TimeWindow(2, 4)));
    assertEquals(TriggerResult.FIRE, testHarness.processElement(new StreamRecord<Object>(1), new TimeWindow(2, 4)));
    // now all state should be gone
    assertEquals(0, testHarness.numStateEntries());
}

