public void testWindowFireWithoutResetTimer() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ProcessingTimeoutTrigger.of(CountTrigger.of(3), Duration.ofMillis(50), false, true), new TimeWindow.Serializer());
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    // Should be two states, one for ProcessingTimeoutTrigger and one for CountTrigger.
    assertEquals(2, testHarness.numStateEntries());
    assertEquals(1, testHarness.numProcessingTimeTimers());
    assertEquals(0, testHarness.numEventTimeTimers());
    // Should not fire before interval time.
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(Long.MIN_VALUE + 40, new TimeWindow(0, 2)));
    assertEquals(TriggerResult.FIRE, testHarness.advanceProcessingTime(Long.MIN_VALUE + 50, new TimeWindow(0, 2)));
    // After firing states should be clear.
    assertEquals(0, testHarness.numStateEntries());
    assertEquals(0, testHarness.numProcessingTimeTimers());
    assertEquals(0, testHarness.numEventTimeTimers());
    // Check inner trigger is working as well
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.FIRE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
}

@Test
public void testWindowFireWithResetTimer() throws Exception {
    TriggerTestHarness<Object, TimeWindow> testHarness = new TriggerTestHarness<>(ProcessingTimeoutTrigger.of(CountTrigger.of(3), Duration.ofMillis(50), true, true), new TimeWindow.Serializer());
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(0, new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(10, new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1), new TimeWindow(0, 2)));
    // Should be two states, one for ProcessingTimeoutTrigger and one for CountTrigger.
    assertEquals(2, testHarness.numStateEntries());
    assertEquals(1, testHarness.numProcessingTimeTimers());
    assertEquals(0, testHarness.numEventTimeTimers());
    // Should not fire at timestampA+interval (at 50 millis), because resetTimer is on, it
    // should fire at 60 millis.
    assertThrows("Must have exactly one timer firing. Fired timers: []", IllegalStateException.class, () -> testHarness.advanceProcessingTime(50, new TimeWindow(0, 2)));
    assertEquals(TriggerResult.FIRE, testHarness.advanceProcessingTime(60, new TimeWindow(0, 2)));
    // After firing states should be clear.
    assertEquals(0, testHarness.numStateEntries());
    assertEquals(0, testHarness.numProcessingTimeTimers());
    assertEquals(0, testHarness.numEventTimeTimers());
    // Check inner trigger is working as well
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1, 0), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.CONTINUE, testHarness.processElement(new StreamRecord<>(1, 10), new TimeWindow(0, 2)));
    assertEquals(TriggerResult.FIRE, testHarness.processElement(new StreamRecord<>(1, 20), new TimeWindow(0, 2)));
}

