public void testErrorMessage() throws Exception {
    // prepare statements which will throw exception
    String stmts = "CREATE TABLE T (a int) WITH ('connector' = 'invalid');\n" + "SELECT * FROM T;\n" + "QUIT;\n";
    String[] args = new String[] {};
    String output = runSqlClient(args, stmts);
    assertThat(output).contains("org.apache.flink.table.api.ValidationException: Could not find any factory for identifier 'invalid'");
