@Test
void testCreateFunction() {
    sql("create function catalog1.db1.function1 as 'org.apache.fink.function.function1'").ok("CREATE FUNCTION `CATALOG1`.`DB1`.`FUNCTION1` AS 'org.apache.fink.function.function1'");
    sql("create temporary function catalog1.db1.function1 as 'org.apache.fink.function.function1'").ok("CREATE TEMPORARY FUNCTION `CATALOG1`.`DB1`.`FUNCTION1` AS 'org.apache.fink.function.function1'");
    sql("create temporary function db1.function1 as 'org.apache.fink.function.function1'").ok("CREATE TEMPORARY FUNCTION `DB1`.`FUNCTION1` AS 'org.apache.fink.function.function1'");
    sql("create temporary function function1 as 'org.apache.fink.function.function1'").ok("CREATE TEMPORARY FUNCTION `FUNCTION1` AS 'org.apache.fink.function.function1'");
    sql("create temporary function if not exists catalog1.db1.function1 as 'org.apache.fink.function.function1'").ok("CREATE TEMPORARY FUNCTION IF NOT EXISTS `CATALOG1`.`DB1`.`FUNCTION1` AS 'org.apache.fink.function.function1'");
    sql("create temporary function function1 as 'org.apache.fink.function.function1' language java").ok("CREATE TEMPORARY FUNCTION `FUNCTION1` AS 'org.apache.fink.function.function1' LANGUAGE JAVA");
    sql("create temporary system function  function1 as 'org.apache.fink.function.function1' language scala").ok("CREATE TEMPORARY SYSTEM FUNCTION `FUNCTION1` AS 'org.apache.fink.function.function1' LANGUAGE SCALA");
    // Temporary system function always belongs to the system and current session.
    sql("create temporary system function catalog1^.^db1.function1 as 'org.apache.fink.function.function1'").fails("(?s).*Encountered \".\" at.*");
    sql("create ^system^ function function1 as 'org.apache.fink.function.function1'").fails("CREATE SYSTEM FUNCTION is not supported, " + "system functions can only be registered as temporary " + "function, you can use CREATE TEMPORARY SYSTEM FUNCTION instead.");
}

