    assertThat(functionCatalog.lookupFunction(FULL_UNRESOLVED_IDENTIFIER)).hasValue(ContextResolvedFunction.temporary(FunctionIdentifier.of(IDENTIFIER), // temporary function hides catalog function
    FUNCTION_1));
    // dropping catalog functions is not possible in this state
    assertThatThrownBy(() -> functionCatalog.dropCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, true)).satisfies(anyCauseMatches(ValidationException.class, "A temporary function '" + IDENTIFIER.asSummaryString() + "' does already exist. " + "Please drop the temporary function first."));
    // registering catalog functions is not possible in this state
    assertThatThrownBy(() -> functionCatalog.registerCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, FUNCTION_2.getClass(), false)).satisfies(anyCauseMatches(ValidationException.class, "A temporary function '" + IDENTIFIER.asSummaryString() + "' does already exist. " + "Please drop the temporary function first."));
    // register temporary second time lenient
    functionCatalog.registerTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, FUNCTION_1, true);
    assertThat(functionCatalog.lookupFunction(FULL_UNRESOLVED_IDENTIFIER)).hasValue(ContextResolvedFunction.temporary(FunctionIdentifier.of(IDENTIFIER), FUNCTION_1));
