    assertThatThrownBy(() -> functionCatalog.registerTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, FUNCTION_2, false)).satisfies(anyCauseMatches(ValidationException.class, "A function '" + IDENTIFIER.asSummaryString() + "' does already exist."));
    // drop temporary first time
    assertThat(functionCatalog.dropTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, false)).isTrue();
    assertThat(functionCatalog.lookupFunction(FULL_UNRESOLVED_IDENTIFIER)).hasValue(ContextResolvedFunction.permanent(FunctionIdentifier.of(IDENTIFIER), // permanent function is visible again
    FUNCTION_2));
    // drop temporary second time lenient
    assertThat(functionCatalog.dropTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, true)).isFalse();
    // drop temporary second time not lenient
    assertThatThrownBy(() -> functionCatalog.dropTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, false)).satisfies(anyCauseMatches(ValidationException.class, "Temporary catalog function " + IDENTIFIER.toString() + " doesn't exist"));
    // register invalid
    assertThatThrownBy(() -> functionCatalog.registerTemporaryCatalogFunction(PARTIAL_UNRESOLVED_IDENTIFIER, FUNCTION_INVALID, false)).satisfies(anyCauseMatches(ValidationException.class, "Could not register temporary catalog function '" + IDENTIFIER.asSummaryString() + "' due to implementation errors."));
}

