@Test
public void testGenerateDecimalValues() {
    for (int precision = 1; precision <= 38; precision++) {
        for (int scale = 0; scale <= precision; scale++) {
            DecimalDataRandomGenerator gen = new DecimalDataRandomGenerator(precision, scale, Double.MIN_VALUE, Double.MAX_VALUE);
            DecimalData value = gen.next();
            assertThat(value).as("Null value for DECIMAL(" + precision + "," + scale + ")").isNotNull();
            String strRepr = String.valueOf(value);
            if (strRepr.charAt(0) == '-') {
                // drop the negative sign
                strRepr = strRepr.substring(1);
            }
            if (scale != precision) {
                // need to account for decimal . and potential leading zeros
                assertThat(strRepr.length()).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).isLessThanOrEqualTo(precision + 1);
            } else {
                // need to account for decimal . and potential leading zeros
                assertThat(strRepr.length()).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).isLessThanOrEqualTo(precision + 2);
            }
            if (scale != 0) {
                String decimalPart = strRepr.split("\\.")[1];
                assertThat(decimalPart.length()).as("Wrong length for DECIMAL(" + precision + "," + scale + ") = " + strRepr).isEqualTo(scale);
            }
        }
    }
}

@Test
public void testMinMax() {
    for (int precision = 1; precision <= 38; precision++) {
        for (int scale = 0; scale <= precision; scale++) {
            BigDecimal min = BigDecimal.valueOf(-10.0);
            BigDecimal max = BigDecimal.valueOf(10.0);
            DecimalDataRandomGenerator gen = new DecimalDataRandomGenerator(precision, scale, min.doubleValue(), max.doubleValue());
            DecimalData result = gen.next();
            assertThat(result).as("Null value for DECIMAL(" + precision + "," + scale + ")").isNotNull();
            assertThat(result.toBigDecimal()).as("value must be greater than or equal to min").isGreaterThanOrEqualTo(min);
            assertThat(result.toBigDecimal()).as("value must be less than or equal to max").isLessThanOrEqualTo(max);
        }
    }
}

