@Test
public void testConstructorCall() {
    String code = "public class A extends B {
" + "  private final int a, b;
" + "  public A(int a) {
" + "    this(a, 0);
" + "  }
" + "  public A(int a, int b) {
" + "    super(a, b);
" + "    this.a = a;
" + "    this.b = b;
" + "  }
" + "}";
    CommonTokenStream tokenStream = new CommonTokenStream(new JavaLexer(CharStreams.fromString(code)));
    JavaParser parser = new JavaParser(tokenStream);
    TestConstructorCallVisitor visitor = new TestConstructorCallVisitor();
    visitor.visit(parser.compilationUnit());
    assertThat(visitor.thisCount).isEqualTo(1);
    assertThat(visitor.superCount).isEqualTo(1);
}

