@Test
public void testMonitorContinuously() throws Exception {
    // Create temp dir
    File testPath = TEMPORARY_FOLDER.newFolder();
    // Write first csv file out
    Files.write(Paths.get(testPath.getPath(), "input_0.csv"), Arrays.asList("1", "2", "3"), StandardOpenOption.CREATE);
    Duration monitorInterval = Duration.ofSeconds(1);
    tEnv().createTable("my_streaming_table", TableDescriptor.forConnector("filesystem").schema(Schema.newBuilder().column("data", DataTypes.INT()).build()).format("testcsv").option(FileSystemConnectorOptions.PATH, testPath.getPath()).option(FileSystemConnectorOptions.SOURCE_MONITOR_INTERVAL, monitorInterval).build());
    List<Integer> actual = new ArrayList<>();
    try (CloseableIterator<Row> resultsIterator = tEnv().sqlQuery("SELECT * FROM my_streaming_table").execute().collect()) {
        // Iterate over the first 3 rows
        for (int i = 0; i < 3; i++) {
            actual.add(resultsIterator.next().<Integer>getFieldAs(0));
        }
        // Write second csv file out
        Files.write(Paths.get(testPath.getPath(), "input_1.csv"), Arrays.asList("4", "5", "6"), StandardOpenOption.CREATE);
        // Iterate over the next 3 rows
        for (int i = 0; i < 3; i++) {
            actual.add(resultsIterator.next().<Integer>getFieldAs(0));
        }
    }
    assertThat(actual).containsExactlyInAnyOrder(1, 2, 3, 4, 5, 6);
}

