@Test
public void testAlterTableCompactOnManagedPartitionedTable() throws Exception {
    prepareManagedTable(true);
    // compact partitioned table with a non-existed partition_spec
    assertThatThrownBy(() -> parse("alter table tb1 partition (dt = 'a') compact", SqlDialect.DEFAULT)).isInstanceOf(ValidationException.class).hasMessage("Partition column 'dt' not defined in the table schema. Available ordered partition columns: ['b', 'c']");
    // compact partitioned table with full partition spec
    Map<String, String> staticPartitions = new HashMap<>();
    staticPartitions.put("b", "0");
    staticPartitions.put("c", "flink");
    checkAlterTableCompact(parse("alter table tb1 partition (b = 0, c = 'flink') compact", SqlDialect.DEFAULT), staticPartitions);
    // compact partitioned table with subordinate partition spec
    staticPartitions = Collections.singletonMap("b", "0");
    checkAlterTableCompact(parse("alter table tb1 partition (b = 0) compact", SqlDialect.DEFAULT), staticPartitions);
    // compact partitioned table with secondary partition spec
    staticPartitions = Collections.singletonMap("c", "flink");
    checkAlterTableCompact(parse("alter table tb1 partition (c = 'flink') compact", SqlDialect.DEFAULT), staticPartitions);
    // compact partitioned table without partition spec
    staticPartitions = Collections.emptyMap();
    checkAlterTableCompact(parse("alter table tb1 compact", SqlDialect.DEFAULT), staticPartitions);
}

