@Test
public void testNullEnforcer() throws ExecutionException, InterruptedException {
    final StreamTableEnvironment tableEnv = StreamTableEnvironment.create(env);
    final List<Row> rows = Arrays.asList(Row.of(1, "Apache", 11), Row.of(2, null, 22), Row.of(null, "Flink", 33), Row.of(null, null, 44));
    final SharedReference<List<RowData>> results = sharedObjects.add(new ArrayList<>());
    tableEnv.createTable("T1", TableFactoryHarness.newBuilder().schema(schemaForNotNullEnforcer()).source(new TestSource(rows)).sink(buildRuntimeSinkProvider(new RecordWriter(results))).build());
    // Default config - ignore (no trim)
    assertThatThrownBy(() -> tableEnv.executeSql("INSERT INTO T1 SELECT * FROM T1").await()).isInstanceOf(ExecutionException.class).satisfies(anyCauseMatches("Column 'b' is NOT NULL, however, a null value is being written into it. " + "You can set job configuration 'table.exec.sink.not-null-enforcer'='DROP' " + "to suppress this exception and drop such records silently."));
    // Test not including a NOT NULL column
    results.get().clear();
    assertThatThrownBy(() -> tableEnv.executeSql("INSERT INTO T1(a, b) SELECT (a, b) FROM T1").await()).isInstanceOf(ValidationException.class).hasMessage("SQL validation failed. At line 0, column 0: Column 'c' has no default " + "value and does not allow NULLs");
    // Change config option to "drop", to drop the columns instead of throwing errors
    try {
        tableEnv.getConfig().set(TABLE_EXEC_SINK_NOT_NULL_ENFORCER.key(), ExecutionConfigOptions.NotNullEnforcer.DROP.name());
        results.get().clear();
        tableEnv.executeSql("INSERT INTO T1 SELECT * FROM T1").await();
        assertThat(results.get().size()).isEqualTo(2);
        assertThat(results.get().get(0).getInt(0)).isEqualTo(1);
        assertThat(results.get().get(0).getString(1).toString()).isEqualTo("Apache");
        assertThat(results.get().get(0).getInt(2)).isEqualTo(11);
        assertThat(results.get().get(1).isNullAt(0)).isTrue();
        assertThat(results.get().get(1).getString(1).toString()).isEqualTo("Flink");
        assertThat(results.get().get(1).getInt(2)).isEqualTo(33);
    } finally {
        tableEnv.getConfig().set(TABLE_EXEC_SINK_NOT_NULL_ENFORCER.key(), ExecutionConfigOptions.NotNullEnforcer.ERROR.name());
    }
}

@Test
public void testFromValuesWatermarkPropagation() throws Exception {
    final StreamTableEnvironment tableEnv = StreamTableEnvironment.create(env);
    final SharedReference<List<Long>> watermarks = sharedObjects.add(new ArrayList<>());
    final SinkFunction<RowData> sinkFunction = new SinkFunction<RowData>() {

        @Override
        public void writeWatermark(org.apache.flink.api.common.eventtime.Watermark watermark) {
            addElement(watermarks, watermark.getTimestamp());
        }
    };
    final TableDescriptor sinkDescriptor = TableFactoryHarness.newBuilder().sink(new TableFactoryHarness.SinkBase() {

        @Override
        public DataStreamSinkProvider getSinkRuntimeProvider(DynamicTableSink.Context context) {
            return (providerContext, dataStream) -> dataStream.addSink(sinkFunction);
        }
    }).build();
    final Table source = tableEnv.fromValues(DataTypes.ROW(DataTypes.FIELD("a", DataTypes.INT())), Row.of(1), Row.of(2), Row.of(3));
    source.executeInsert(sinkDescriptor).await();
    assertThat(watermarks.get().size()).isEqualTo(env.getParallelism());
    for (Long watermark : watermarks.get()) {
        assertThat(watermark).isEqualTo(Watermark.MAX_WATERMARK.getTimestamp());
    }
}

