@Test
public void testLegacyUid() {
    final TableEnvironment env = TableEnvironment.create(EnvironmentSettings.inStreamingMode().getConfiguration());
    env.getConfig().set(ExecutionConfigOptions.TABLE_EXEC_LEGACY_TRANSFORMATION_UIDS, true);
    env.createTemporaryTable("source_table", TableDescriptor.forConnector("values").option("bounded", "true").schema(dummySchema()).build());
    env.createTemporaryTable("sink_table", TableDescriptor.forConnector("values").schema(dummySchema()).build());
    final CompiledPlan compiledPlan = env.from("source_table").select($("i").abs()).insertInto("sink_table").compilePlan();
    // There should be 3 transformations in this list: sink -> calc -> source
    final List<Transformation<?>> transformations = CompiledPlanUtils.toTransformations(env, compiledPlan).get(0).getTransitivePredecessors();
    assertThat(transformations).hasSize(3);
    // As the sink and source might set the uid, we only check the calc transformation.
    assertThat(transformations).element(1, type(Transformation.class)).extracting(Transformation::getUid).isNull();
}

