@Test
public void testCompactMultiPartitionedTable() throws Exception {
    String sql = "CREATE TABLE MyTable (" + "  id BIGINT,\n" + "  content STRING,\n" + "  season STRING,\n" + "  `month` INT\n" + ") PARTITIONED BY (season, `month`)";
    prepare(sql, Arrays.asList(// spring
    of("season", "'spring'", "`month`", "2"), of("season", "'spring'", "`month`", "3"), of("season", "'spring'", "`month`", "4"), // summer
    of("season", "'summer'", "`month`", "5"), of("season", "'summer'", "`month`", "6"), of("season", "'summer'", "`month`", "7"), of("season", "'summer'", "`month`", "8"), // autumn
    of("season", "'autumn'", "`month`", "8"), of("season", "'autumn'", "`month`", "9"), of("season", "'autumn'", "`month`", "10"), // winter
    of("season", "'winter'", "`month`", "11"), of("season", "'winter'", "`month`", "12"), of("season", "'winter'", "`month`", "1")));
    Set<CatalogPartitionSpec> resolvedPartitionSpecsHaveBeenOrToBeCompacted = new HashSet<>();
    // test compact one partition with full ordered partition spec
    CatalogPartitionSpec unresolvedPartitionSpec = new CatalogPartitionSpec(of("season", "'spring'", "`month`", "2"));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "spring", "month", "2")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
    // test compact one partition with full but disordered partition spec
    unresolvedPartitionSpec = new CatalogPartitionSpec(of("`month`", "3", "season", "'spring'"));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "spring", "month", "3")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
    // test compact multiple partitions with the subordinate partition spec
    unresolvedPartitionSpec = new CatalogPartitionSpec(of("season", "'winter'"));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "winter", "month", "1")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "winter", "month", "11")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "winter", "month", "12")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
    // test compact one partition with the secondary partition spec
    unresolvedPartitionSpec = new CatalogPartitionSpec(of("`month`", "5"));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "summer", "month", "5")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
    // test compact multiple partitions with the secondary partition spec
    unresolvedPartitionSpec = new CatalogPartitionSpec(of("`month`", "8"));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "summer", "month", "8")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "autumn", "month", "8")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
    // test compact the whole table
    unresolvedPartitionSpec = new CatalogPartitionSpec(Collections.emptyMap());
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "spring", "month", "4")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "summer", "month", "6")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "summer", "month", "7")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "autumn", "month", "9")));
    resolvedPartitionSpecsHaveBeenOrToBeCompacted.add(new CatalogPartitionSpec(of("season", "autumn", "month", "10")));
    executeAndCheck(unresolvedPartitionSpec, resolvedPartitionSpecsHaveBeenOrToBeCompacted);
}

