@Test
public void testTableSourceFactory() {
    tEnv().createTemporaryTable("T", TableFactoryHarness.newBuilder().schema(Schema.newBuilder().build()).source(new TableFactoryHarness.ScanSourceBase() {

        @Override
        public ScanRuntimeProvider getScanRuntimeProvider(ScanContext runtimeProviderContext) {
            throw new UnsupportedOperationException("Discovered factory should not be used");
        }
    }).build());
    final Table table = tEnv().from("T");
    // Sanity check: without our module loaded, the factory discovery process is used.
    assertThatThrownBy(table::explain).as("Discovered factory should not be used").isInstanceOf(UnsupportedOperationException.class);
    // The module has precedence over factory discovery.
    tEnv().loadModule("M", new SourceSinkFactoryOverwriteModule());
    table.explain();
}

