    ObjectPath objectPath = new ObjectPath("default_database", "f3");
    assertThat(tEnv().getCatalog("default_catalog")).isPresent();
    Catalog catalog = tEnv().getCatalog("default_catalog").get();
    tEnv().executeSql(create);
