@Test
public void testWithParallelism() throws Exception {
    tEnv().executeSql("create table print_t (" + "f0 int," + "f1 double" + ") with (" + "'connector' = 'print'," + "'print-identifier' = 'test_print'," + "'sink.parallelism' = '2'," + "'standard-error'='false')");
    DataType type = tEnv().from("print_t").getResolvedSchema().toPhysicalRowDataType();
    Row row = Row.of(1, 1.1);
    tEnv().fromValues(type, Collections.singleton(row)).executeInsert("print_t").await();
    String expectedLine1 = "test_print:1> +I[" + /* 0 */
    "1, " + /* 1 */
    "1.1" + "]";
    String expectedLine2 = "test_print:2> +I[" + /* 0 */
    "1, " + /* 1 */
    "1.1" + "]";
    assertThat(arrayOutputStream.toString().equals(expectedLine1 + "\n") || arrayOutputStream.toString().equals(expectedLine2 + "\n")).isTrue();
}

