@Test
public void testLegacyShuffleMode() {
    final Configuration configuration = new Configuration();
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, GlobalStreamExchangeMode.ALL_EDGES_BLOCKING.toString());
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, GlobalStreamExchangeMode.FORWARD_EDGES_PIPELINED.toString());
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.FORWARD_EDGES_PIPELINED);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, GlobalStreamExchangeMode.POINTWISE_EDGES_PIPELINED.toString());
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.POINTWISE_EDGES_PIPELINED);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, GlobalStreamExchangeMode.ALL_EDGES_PIPELINED.toString());
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.ALL_EDGES_PIPELINED);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, StreamExchangeModeUtils.ALL_EDGES_BLOCKING_LEGACY);
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.ALL_EDGES_BLOCKING);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, StreamExchangeModeUtils.ALL_EDGES_PIPELINED_LEGACY);
    assertThat(getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.ALL_EDGES_PIPELINED);
    configuration.setString(ExecutionConfigOptions.TABLE_EXEC_SHUFFLE_MODE, "Forward_edges_PIPELINED");
    assertThat(StreamExchangeModeUtils.getGlobalStreamExchangeMode(configuration).orElseThrow(AssertionError::new)).isEqualTo(GlobalStreamExchangeMode.FORWARD_EDGES_PIPELINED);
}

