@Test
public void testEmptyString() {
    BinaryStringData str2 = fromString("hahahahah");
    BinaryStringData str3;
    {
        MemorySegment[] segments = new MemorySegment[2];
        segments[0] = MemorySegmentFactory.wrap(new byte[10]);
        segments[1] = MemorySegmentFactory.wrap(new byte[10]);
        str3 = BinaryStringData.fromAddress(segments, 15, 0);
    }
    assertThat(BinaryStringData.EMPTY_UTF8.compareTo(str2)).isLessThan(0);
    assertThat(str2.compareTo(BinaryStringData.EMPTY_UTF8)).isGreaterThan(0);
    assertThat(BinaryStringData.EMPTY_UTF8.compareTo(str3)).isEqualTo(0);
    assertThat(str3.compareTo(BinaryStringData.EMPTY_UTF8)).isEqualTo(0);
    assertThat(str2).isNotEqualTo(BinaryStringData.EMPTY_UTF8);
    assertThat(BinaryStringData.EMPTY_UTF8).isNotEqualTo(str2);
    assertThat(str3).isEqualTo(BinaryStringData.EMPTY_UTF8);
    assertThat(BinaryStringData.EMPTY_UTF8).isEqualTo(str3);
}

@Test
public void testEncodeWithIllegalCharacter() throws UnsupportedEncodingException {
    // Tis char array has some illegal character, such as 55357
    // the jdk ignores theses character and cast them to '?'
    // which StringUtf8Utils'encodeUTF8 should follow
    char[] chars = new char[] { 20122, 40635, 124, 38271, 34966, 124, 36830, 34915, 35033, 124, 55357, 124, 56407 };
    String str = new String(chars);
    assertThat(StringUtf8Utils.encodeUTF8(str)).isEqualTo(str.getBytes("UTF-8"));
}

@Test
public void testKeyValue() {
    assertThat(keyValue(fromString("k1:v1|k2:v2"), fromString("|").byteAt(0), fromString(":").byteAt(0), fromString("k3"))).isNull();
    assertThat(keyValue(fromString("k1:v1|k2:v2|"), fromString("|").byteAt(0), fromString(":").byteAt(0), fromString("k3"))).isNull();
    assertThat(keyValue(fromString("|k1:v1|k2:v2|"), fromString("|").byteAt(0), fromString(":").byteAt(0), fromString("k3"))).isNull();
    String tab = org.apache.commons.lang3.StringEscapeUtils.unescapeJava("\t");
    assertThat(keyValue(fromString("k1:v1" + tab + "k2:v2"), fromString("\t").byteAt(0), fromString(":").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
    assertThat(keyValue(fromString("k1:v1|k2:v2"), fromString("|").byteAt(0), fromString(":").byteAt(0), null)).isNull();
    assertThat(keyValue(fromString("k1=v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
    assertThat(keyValue(fromString("|k1=v1|k2=v2|"), fromString("|").byteAt(0), fromString("=").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
    assertThat(keyValue(fromString("k1=v1||k2=v2"), fromString("|").byteAt(0), fromString("=").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
    assertThat(keyValue(fromString("k1=v1;k2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k2"))).isNull();
    assertThat(keyValue(fromString("k1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1"))).isNull();
    assertThat(keyValue(fromString("k=1=v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k="))).isNull();
    assertThat(keyValue(fromString("k1==v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1"))).isEqualTo(fromString("=v1"));
    assertThat(keyValue(fromString("k1==v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1="))).isNull();
    assertThat(keyValue(fromString("k1=v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1="))).isNull();
    assertThat(keyValue(fromString("k1k1=v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1"))).isNull();
    assertThat(keyValue(fromString("k1=v1;k2=v2"), fromString(";").byteAt(0), fromString("=").byteAt(0), fromString("k1k1k1k1k1k1k1k1k1k1"))).isNull();
    assertThat(keyValue(fromString("k1:v||k2:v2"), fromString("|").byteAt(0), fromString(":").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
    assertThat(keyValue(fromString("k1:v||k2:v2"), fromString("|").byteAt(0), fromString(":").byteAt(0), fromString("k2"))).isEqualTo(fromString("v2"));
}

@Test
public void testDecodeWithIllegalUtf8Bytes() throws UnsupportedEncodingException {
    // illegal utf-8 bytes
    byte[] bytes = new byte[] { (byte) 20122, (byte) 40635, 124, (byte) 38271, (byte) 34966, 124, (byte) 36830, (byte) 34915, (byte) 35033, 124, (byte) 55357, 124, (byte) 56407 };
    String str = new String(bytes, StandardCharsets.UTF_8);
    assertThat(StringUtf8Utils.decodeUTF8(bytes, 0, bytes.length)).isEqualTo(str);
    assertThat(StringUtf8Utils.decodeUTF8(MemorySegmentFactory.wrap(bytes), 0, bytes.length)).isEqualTo(str);
    byte[] newBytes = new byte[bytes.length + 5];
    System.arraycopy(bytes, 0, newBytes, 5, bytes.length);
    assertThat(StringUtf8Utils.decodeUTF8(MemorySegmentFactory.wrap(newBytes), 5, bytes.length)).isEqualTo(str);
}

@Test
public void skipWrongFirstByte() {
    int[] wrongFirstBytes = { 0x80, 0x9F, // Skip Continuation bytes
    0xBF, 0xC0, // 0xC0..0xC1 - disallowed in UTF-8
    0xC2, // 0xF5..0xFF - disallowed in UTF-8
    0xF5, 0xF6, 0xF7, 0xF8, 0xF9, 0xFA, 0xFB, 0xFC, 0xFD, 0xFE, 0xFF };
    byte[] c = new byte[1];
    for (int wrongFirstByte : wrongFirstBytes) {
        c[0] = (byte) wrongFirstByte;
        assertThat(1).isEqualTo(fromBytes(c).numChars());
    }
}

