@Test
public void testSimple() throws Exception {
    @SuppressWarnings("unchecked")
    TestMapBundleFunction func = new TestMapBundleFunction();
    CountBundleTrigger<Tuple2<String, String>> trigger = new CountBundleTrigger<>(3);
    KeySelector<Tuple2<String, String>, String> keySelector = (KeySelector<Tuple2<String, String>, String>) value -> value.f0;
    OneInputStreamOperatorTestHarness<Tuple2<String, String>, String> op = new OneInputStreamOperatorTestHarness<>(new MapBundleOperator<>(func, trigger, keySelector));
    op.open();
    synchronized (op.getCheckpointLock()) {
        StreamRecord<Tuple2<String, String>> input = new StreamRecord<>(null);
        input.replace(new Tuple2<>("k1", "v1"));
        op.processElement(input);
        input.replace(new Tuple2<>("k1", "v2"));
        op.processElement(input);
        assertThat(func.getFinishCount()).isEqualTo(0);
        input.replace(new Tuple2<>("k2", "v3"));
        op.processElement(input);
        assertThat(func.getFinishCount()).isEqualTo(1);
        assertThat(Arrays.asList("k1=v1,v2", "k2=v3")).isEqualTo(func.getOutputs());
        input.replace(new Tuple2<>("k3", "v4"));
        op.processElement(input);
        input.replace(new Tuple2<>("k4", "v5"));
        op.processElement(input);
        assertThat(func.getFinishCount()).isEqualTo(1);
        op.close();
        assertThat(func.getFinishCount()).isEqualTo(2);
        assertThat(Arrays.asList("k3=v4", "k4=v5")).isEqualTo(func.getOutputs());
    }
}

