    TableOperatorWrapper<?> calcWrapper1 = createWrapper(calc1, 2, 1.0 / 3);
    TableOperatorWrapper<?> calcWrapper2 = createWrapper(calc2, 3, 1.0 / 3);
    TableOperatorWrapper<?> unionWrapper = createWrapper(union, 1);
    unionWrapper.addInput(calcWrapper1, 1);
    unionWrapper.addInput(calcWrapper2, 2);
    TableOperatorWrapper<?> outputWrapper = createWrapper(join, 0, 1.0 / 3);
    outputWrapper.addInput(unionWrapper, 2);
    assertThat(generator.getInputTransformAndInputSpecPairs()).isEqualTo(Arrays.asList(Pair.of(source1, new InputSpec(1, 1, calcWrapper1, 1)), Pair.of(source2, new InputSpec(2, 1, calcWrapper2, 1)), Pair.of(source3, new InputSpec(3, 0, outputWrapper, 2))));
    assertThat(unionWrapper.getInputEdges()).isEqualTo(Arrays.asList(new TableOperatorWrapper.Edge(calcWrapper1, unionWrapper, 1), new TableOperatorWrapper.Edge(calcWrapper2, unionWrapper, 2)));
    assertThat(outputWrapper.getInputEdges()).containsExactly(new TableOperatorWrapper.Edge(unionWrapper, outputWrapper, 2));
    assertThat(generator.getTailWrapper()).isEqualTo(outputWrapper);
    assertThat(generator.getManagedMemoryWeight()).isEqualTo(3);
    assertThat(generator.getParallelism()).isEqualTo(200);
    assertThat(generator.getMaxParallelism()).isEqualTo(-1);
    assertThat(generator.getMinResources()).isEqualTo(ResourceSpec.UNKNOWN);
    assertThat(generator.getPreferredResources()).isEqualTo(ResourceSpec.UNKNOWN);
}

