@Test
public void testDstSaving() {
    if (!TimeZone.getTimeZone(shiftTimeZone).useDaylightTime()) {
        return;
    }
    SliceAssigner assigner = SliceAssigners.cumulative(0, shiftTimeZone, Duration.ofHours(4), Duration.ofHours(1));
    // Los_Angeles local time in epoch mills.
    // The DaylightTime in Los_Angele start at time 2021-03-14 02:00:00
    // 2021-03-14 00:00:00
    long epoch1 = 1615708800000L;
    // 2021-03-14 01:00:00
    long epoch2 = 1615712400000L;
    // 2021-03-14 03:00:00, skip one hour (2021-03-14 02:00:00)
    long epoch3 = 1615716000000L;
    // 2021-03-14 04:00:00
    long epoch4 = 1615719600000L;
    assertSliceStartEnd("2021-03-14T00:00", "2021-03-14T01:00", epoch1, assigner);
    assertSliceStartEnd("2021-03-14T00:00", "2021-03-14T02:00", epoch2, assigner);
