@Test
public void testEventTimeCumulativeWindowsWithLateArrival() throws Exception {
    WindowOperator operator = WindowOperatorBuilder.builder().withInputFields(inputFieldTypes).withShiftTimezone(shiftTimeZone).cumulative(Duration.ofSeconds(3), Duration.ofSeconds(1)).withEventTime(2).withAllowedLateness(Duration.ofMillis(500)).produceUpdates().aggregateAndBuild(new SumAndCountAggTimeWindow(), equaliser, accTypes, aggResultTypes, windowTypes);
    OneInputStreamOperatorTestHarness<RowData, RowData> testHarness = createTestHarness(operator);
    ConcurrentLinkedQueue<Object> expectedOutput = new ConcurrentLinkedQueue<>();
    testHarness.open();
    testHarness.processElement(insertRecord("key2", 1, 500L));
    testHarness.processWatermark(new Watermark(1500));
    expectedOutput.add(insertRecord("key2", 1L, 1L, localMills(0L), localMills(1000L), localMills(999L)));
    expectedOutput.add(new Watermark(1500));
    testHarness.processElement(insertRecord("key2", 1, 1300L));
    testHarness.processWatermark(new Watermark(2300));
    expectedOutput.add(insertRecord("key2", 2L, 2L, localMills(0L), localMills(2000L), localMills(1999L)));
    expectedOutput.add(new Watermark(2300));
    // this will not be dropped because window.maxTimestamp() + allowedLateness >
    // currentWatermark
    testHarness.processElement(insertRecord("key2", 1, 1997L));
    testHarness.processWatermark(new Watermark(6000));
    // this is 1 and not 3 because the trigger fires and purges
    expectedOutput.add(updateBeforeRecord("key2", 2L, 2L, localMills(0L), localMills(2000L), localMills(1999L)));
    expectedOutput.add(updateAfterRecord("key2", 3L, 3L, localMills(0L), localMills(2000L), localMills(1999L)));
    expectedOutput.add(insertRecord("key2", 3L, 3L, localMills(0L), localMills(3000L), localMills(2999L)));
    expectedOutput.add(new Watermark(6000));
    // this will be dropped because window.maxTimestamp() + allowedLateness < currentWatermark
    testHarness.processElement(insertRecord("key2", 1, 1998L));
    testHarness.processWatermark(new Watermark(7000));
    expectedOutput.add(new Watermark(7000));
    assertor.assertOutputEqualsSorted("Output was not correct.", expectedOutput, testHarness.getOutput());
    assertThat(operator.getNumLateRecordsDropped().getCount()).isEqualTo(1);
    testHarness.close();
}

