    assertThat(toEpochMillsForTimer(utcMills("1970-01-01T00:00:01"), zoneId)).isEqualTo(-28799000L);
    assertThat(toEpochMillsForTimer(utcMills("1970-01-01T07:59:59.999"), zoneId)).isEqualTo(-1L);
    assertThat(toEpochMillsForTimer(utcMills("1970-01-01T08:00:01"), zoneId)).isEqualTo(1000L);
    assertThat(toEpochMillsForTimer(utcMills("1970-01-01T08:00:00.001"), zoneId)).isEqualTo(1L);
