    assertThat(toEpochMillsForTimer(utcMills("2021-11-07T02:00:00"), zoneId)).isEqualTo(1636279200000L);
    assertThat(toEpochMillsForTimer(utcMills("2021-11-07T00:00:01"), zoneId)).isEqualTo(1636268401000L);
    assertThat(toEpochMillsForTimer(utcMills("2021-11-07T01:59:59"), zoneId)).isEqualTo(1636279199000L);
    assertThat(toEpochMillsForTimer(utcMills("2021-11-07T02:00:01"), zoneId)).isEqualTo(1636279201000L);
    assertThat(toEpochMills(utcMills("2021-11-07T00:00:00"), zoneId)).isEqualTo(1636268400000L);
    assertThat(toEpochMills(utcMills("2021-11-07T01:00:00"), zoneId)).isEqualTo(1636272000000L);
